INSERT INTO meta(key,value) VALUES('created_at','2026-08-26T08:29:24Z');
INSERT INTO meta(key,value) VALUES('project','open-sample-manager');
INSERT INTO meta(key,value) VALUES('schema_version','1');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-001','constraint','Licensing: Apache-2.0 for code, CC-BY-4.0 for content','Apache-2.0 / CC-BY-4.0.','spec:§1','must','','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-002','constraint','OSM must not be a LabKey UI clone','Kein LabKey-UI-Klon. OSM has its own UX (§12) and is independent of LabKey products.','spec:§1','must','','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-003','constraint','LabKey is strictly downstream','LabKey ist Downstream. OSM is the system of record; LabKey CE is a publish target only.','spec:§1,§16','must','','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-004','constraint','Signed notebooks are immutable','Signed unveraenderlich. No update path may mutate a signed notebook.','spec:§7','must','','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-005','constraint','The UI is a client of the same API the MCP server exposes','MCP a UI: no privileged back door for the UI; both go through the same API and authorisation.','spec:§8,§10','must','','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-006','constraint','Auditor role is read-only','Auditor nur lesen: the auditor can read the trail and nothing else.','spec:§9,§11','must','','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-007','constraint','DPIA required before any USB identifier is processed','DPIA vor USB-Identifikatoren.','spec:§15','must','','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-008','constraint','LabKey server audit supplements but never replaces the OSM trail','audit (Server) zusaetzlicher Trail - nicht OSM ersetzen.','spec:§16.1','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-009','constraint','Study publish requires Subject and Timepoint, otherwise reject','P-LK-STUDY: Subject+Visit, sonst reject.','spec:§17.3','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-010','constraint','At most one unsafe write chain per turn','Maximal eine unsichere Schreibkette pro Turn.','spec:§18.3','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-011','constraint','RAG corpus limited to SOPs, templates and schemas','RAG nur auf SOPs, Templates, Schemata; nicht auf PHI-ELN oder USB-Dateien.','spec:§18.3','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-012','constraint','Prompt injection in an SOP PDF must not unlock extra tools','Injection in SOP-PDF darf keine Extra-Tools freischalten. The tool allowlist is bound to the session, never to document content.','spec:§18.3','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-013','constraint','Iteration acceptance gates','I0 Auth/Audit/OpenAPI done when the hash chain verifies; I1 Registry done at aliquot; I2 Freezer map done per §5; I3 Workflow done at queue; I4 ELN done at signature; I5 Search done with RLS; I6 MCP+LabKey bridge done when the UI runs through MCP semantics; I7 Operations done at the runbook.','spec:§13','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-014','constraint','Freezer map, job queue, ELN and finder have independent acceptance','Freezer-Map, Job-Queue, ELN und Finder haben eigene Abnahmen.','spec:§19','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-015','constraint','Lineage and timeline must not leak identifiers across a permission boundary','A lineage graph, a sample timeline and an ELN reference list must not disclose the name, id or existence detail of an object the caller may not read. LabKey took both available positions: ''Enhanced security by removing access or identifiers to data in different projects in lineage, sample timeline and ELNs'' (23.7), then ''Restricted Lineage Entities - Entities you do not have access to in lineage views are now shown as restricted rather than being omitted, preserving full context without exposing details'' (LIMS 26.2). OSM must choose one deliberately and test it. PR-029''s RLS acceptance test today proves only that a sample grid is scoped; the lineage and timeline paths are separate queries and are the ones that leak. Sources: https://www.labkey.org/Documentation/Archive/23.7/wiki-page.view?name=releaseNotes237 and https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:releaseNotes237','must','I5','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-016','constraint','Publishing targets the container it writes into; cross-folder import is unavailable','The outbox worker must issue each import against the LabKey container that is to receive the rows, and must not rely on importing into one container from another. LabKey: ''Cross-Folder Import Removed - Importing samples, sources, or registry entries into a folder other than the current one is no longer supported'' (LIMS 26.7). A bridge that batches rows for several containers into one call will fail on 26.7 and later. Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-26.7','must','I6','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-017','constraint','The bridge must not lower LabKey''s audit level, and must not assume it can','The publish bridge must not pass an audit-suppressing parameter, and must not depend on suppression working. LabKey: ''Detailed audit logging is automatically enabled for Samples, Sources, Data Classes, and Assay Data, ensuring greater compliance and confidence that all user actions, particularly those occurring via Client APIs, are fully tracked'' and ''API users are now prevented from reducing the audit level below the effective default or the administrator-configured value'' (25.11, Community Edition); ''Client APIs respect the system-configured audit level; when both specify a level, the higher applies'' (LIMS 25.9). This is aligned with CON-008 rather than in tension with it: the LabKey trail supplements the OSM trail and never replaces it, and a bridge that tried to quieten it would be defeating a control, not tuning a knob. Source: https://www.labkey.org/Documentation/Archive/25.11/wiki-page.view?name=releaseNotes2511','labkey:releaseNotes2511','must','I6','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('CON-018','constraint','The bridge pins the LabKey version it targets and re-verifies on upgrade','The bridge records the LabKey version it was verified against, and a version change fails the integration suite until the claims are re-verified. In eighteen months LabKey moved workflow tables out of the sampleManagement schema into a new workflow schema (26.3, effective 26.1), renamed the storage removal action from Discard to Remove and the subcontainer from Project to Folder (LIMS 24.10), removed cross-folder import (26.7) and removed the Derive Samples UI (26.7). None was announced as a breaking API change. Sources: https://www.labkey.org/Documentation/Archive/26.3/wiki-page.view?name=releaseNotes263 and https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:releaseNotes263','must','I6','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-001','functional','Register, store, process, document and search samples','OSM registriert, lagert, bearbeitet, dokumentiert und sucht Proben. It is the System of Record for the sample lifecycle.','spec:§1','must','I1','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-002','functional','Chain of custody for every sample','Every custody transfer (intake, move, ship, discard) is recorded and attributable to an actor.','spec:§1','must','I0','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-003','functional','Freezer map with 1:1 physical correspondence','The storage model mirrors the physical freezer layout exactly (Freezer-Map 1:1); one slot holds at most one sample.','spec:§1,§5','must','I2','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-004','functional','SOP-driven jobs with a work queue','SOP-Jobs mit Queue: templates instantiate jobs whose tasks appear in per-user and per-project queues.','spec:§1,§6','must','I3','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-005','functional','Electronic lab notebook with signature','ELN mit Signatur: notebooks progress draft->review->approved->signed->locked.','spec:§1,§7','must','I4','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-006','functional','Faceted search across samples, lineage, storage and assays','Facettierte Suche (Finder).','spec:§1,§8','must','I5','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-007','functional','Hash-chained audit trail','Hash-Audit: append-only audit with SHA-256 chaining.','spec:§1,§9','must','I0','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-008','functional','REST API plus MCP server','REST plus MCP. MCP tools mirror REST semantics exactly.','spec:§1,§10','must','I6','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-009','functional','Publish to LabKey CE without addWebPart','LabKey-Publish ohne addWebPart. Portals are delivered as folder.xml zip archives instead.','spec:§1,§16','must','I6','open','2026-08-26T08:31:35Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-010','functional','Service decomposition into eleven domain services','identity, registry, storage, workflow, eln, search, audit, file, labkey-bridge, mcp-server, notify.','spec:§2','must','I0','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-011','functional','Every write is audited in the same transaction','Jede Schreiboperation auditiert in derselben Transaktion. Audit write and domain write share one DB transaction; no post-hoc auditing.','spec:§2','must','I0','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-012','functional','PostgreSQL with row-level security','PostgreSQL mit RLS as the persistence layer; object store for files.','spec:§2','must','I5','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-013','functional','OIDC authentication, roles and API keys','identity-service provides OIDC login, role assignment and API keys for machine clients.','spec:§2','must','I0','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-014','functional','Core entities: Project, SampleType, Source, Sample','Project(project_id: name, retention); SampleType(sample_type_id: pattern, fields, statuses); Source(source_id: human_id, meta); Sample(sample_id: status, barcode, slot).','spec:§3','must','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-015','functional','AliquotLink models aliquot and derived relations','AliquotLink(parent+child) with kind in {aliquot, derived}.','spec:§3','must','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-016','functional','StorageNode and Slot entities with geometry and occupancy','StorageNode/Slot carry geometry and occupied_by.','spec:§3','must','I2','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-017','functional','Job and Task entities','Job/Task with owner, due date and status.','spec:§3','must','I3','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-018','functional','Notebook entity with status and content hash','Notebook(notebook_id: status, hash).','spec:§3','must','I4','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-019','functional','AssayRun entity linking a design to samples','AssayRun(run_id: design, samples).','spec:§3','should','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-020','functional','AuditEvent stores before/after state and previous hash','AuditEvent(event_id: before, after, prev_hash).','spec:§3','must','I0','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-021','functional','PublishOutbox entity for LabKey delivery','PublishOutbox(outbox_id: target, state); the transactional outbox pattern decouples OSM writes from LabKey publishing.','spec:§3,§16.2','must','I6','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-022','functional','Eight sample lifecycle statuses','Registered -> Available -> Reserved -> In Process -> Consumed | Locked | Discarded | Shipped.','spec:§3','must','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-023','functional','Sample type designer','Users define sample types: naming pattern, custom fields, permitted statuses.','spec:§4','must','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-024','functional','CSV bulk intake of samples','CSV import path for registering samples in bulk.','spec:§4','must','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-025','functional','Create aliquots and derivatives','Aliquot (same type, split amount) and Derivat (new type, parent link) operations.','spec:§4','must','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-026','functional','Sample timeline view','Chronological timeline of every event affecting a sample.','spec:§4','must','I1','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-027','functional','Picklists','Named, ordered working sets of samples that can start a job.','spec:§4,§17.2','must','I5','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-028','functional','Five-level storage hierarchy','site/building/room (list) -> device (status, zone) -> rack/drawer (grid, capacity) -> box/plate (rows x cols, A1 origin) -> slot (cell, one sample).','spec:§5','must','I2','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-029','functional','Atomic check-in, check-out and move','Check-in/out/Move atomar. A move either fully succeeds or leaves both slots unchanged.','spec:§5','must','I2','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-030','functional','Box move as an atomic batch','Box-Move als Batch: relocating a box moves all contained samples in one transaction.','spec:§5','must','I2','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-031','functional','TTL-based slot reservation','TTL-Reservierung: a slot can be reserved for a bounded time and is released automatically on expiry.','spec:§5','must','I2','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-032','functional','Slot conflict returns HTTP 409','Slot-Konflikt 409. Occupancy is enforced by a database constraint, not by application checks alone.','spec:§5','must','I2','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-033','functional','Job templates are defined without samples','Templates ohne Proben: a template is a reusable SOP skeleton; samples are bound at job start.','spec:§6','must','I3','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-034','functional','Queue views: my tasks, active jobs, board','Queue: meine Tasks, Active Jobs, Board.','spec:§6','must','I3','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-035','functional','Due-date escalation at T-1 and T+1','Eskalation T-1/T+1: notify before and after the due date.','spec:§6','must','I3','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-036','functional','Optimistic locking on task completion','Optimistic Lock auf complete: concurrent completion of the same task is rejected.','spec:§6','must','I3','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-037','functional','ELN state machine draft->review->approved->signed->locked','Only forward transitions; signed entries are immutable.','spec:§7','must','I4','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-038','functional','Signature requires re-authentication and a JSON hash','Signatur mit Re-Auth und JSON-Hash: the canonical JSON of the notebook is hashed and bound to the signer.','spec:§7','must','I4','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-039','functional','Search facets over type, lineage, storage and assay thresholds','Facetten, Lineage, Lager, Assay-Schwellen.','spec:§8','must','I5','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-040','functional','Append-only audit with SHA-256 hash chain','Each event stores prev_hash; tampering breaks the chain.','spec:§9','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-041','functional','Daily audit checkpoint','Tages-Checkpoint anchors the chain so verification does not need a full replay.','spec:§9','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-042','functional','Audit trail export','Trail-Export for an entity or a time range.','spec:§9','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-043','functional','Core REST endpoints','POST /samples (intake), POST /storage/moves, POST /jobs, POST /notebooks/{id}/sign, GET /search.','spec:§10','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-044','functional','MCP tool namespaces mirror REST semantics','osm.samples.*, osm.storage.*, osm.jobs.*, osm.eln.append_ref (draft only), osm.audit.for_entity, osm.labkey.publish_status.','spec:§10','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-045','functional','Destructive actions require confirm=true and osm.admin.write','confirm=true plus osm.admin.write fuer destruktive Aktionen.','spec:§10','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-046','functional','Audit records actor_type=mcp for agent-initiated writes','actor_type=mcp im Audit distinguishes agent actions from human actions.','spec:§10','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-047','functional','Seven-role authorisation model','Reader (read); Technician (create, store, own tasks); Scientist (jobs, ELN draft, assays); Reviewer (sign); Storage/Workflow admin (structure); Project admin (types, members); Auditor (trail only).','spec:§11','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-048','functional','Own UX with eight top-level areas','Dashboard, Samples, Sources, Map, Workflow, ELN, Finder, Admin.','spec:§12','must','I1','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-049','functional','Temperature logger integration (open)','Temperatur-Logger. Unresolved in the spec; treat as a deferred integration.','spec:§15','could','I7','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-050','functional','ZPL label printer support (open)','ZPL-Drucker. Unresolved in the spec.','spec:§15','could','I2','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-051','functional','Publish to LabKey using CSRF, createContainer, Domain, query-import, wiki-save, WebDAV','APIs wie UCI/Biomed. Reuse the established script conventions.','spec:§16','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-052','functional','Map OSM objects onto LabKey modules','Sample/Aliquot/Lineage -> experiment Sample Types; Source -> Data Classes; AssayRun -> assay; catalogs -> list; file pointers -> pipeline/filecontent via WebDAV; SOPs -> wiki; charts -> visualization.','spec:§16.1','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-053','functional','Publish mapping rules','Project -> LabKey project/subfolder; human_id unique plus AutoIncrement key; lineage as lookups; storage_path as a plain string (the map stays in OSM); jobs as a list read-model; ELN PDF to @files/eln/.','spec:§16.2','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-054','functional','osm_id carried into LabKey for idempotent publishing','osm_id fuer Idempotenz: re-publishing the same object must not duplicate rows.','spec:§16.2','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-055','functional','Outbox worker consumes sample.committed, assay.uploaded, notebook.signed','labkey-bridge (I6) arbeitet osm_publish_queue ab. Failures are stored as FAILED including the HTTP response body.','spec:§16.2','must','I6','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-056','functional','Uniform pipeline shape','Trigger -> Validierung -> Aktion -> Audit -> optional Notify/Publish/LLM. Every pipeline follows this shape.','spec:§17','must','I1','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-057','functional','Inventory pipelines P-INTAKE, P-ALIQUOT, P-DERIVE','P-INTAKE (type, id, source, slot, label); P-ALIQUOT (amount, children, lineage); P-DERIVE (type change plus parent).','spec:§17.1','must','I1','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-058','functional','Storage pipelines P-CHECKIN, P-CHECKOUT, P-BOXMOVE, P-DISCARD, P-SHIP','P-CHECKIN (occupy); P-CHECKOUT (free, Reserved); P-BOXMOVE (atomic batch); P-DISCARD (status, free slot); P-SHIP (custody, Shipped).','spec:§17.1','must','I2','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-059','functional','Work pipelines P-JOB-START, P-JOB-TASK, P-JOB-BLOCK','P-JOB-START (template+samples -> tasks, queue, notify); P-JOB-TASK (checklist, next step); P-JOB-BLOCK (escalation).','spec:§17.2','must','I3','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-060','functional','Documentation pipelines P-ASSAY-UP, P-ELN-DRAFT, P-ELN-REVIEW, P-ELN-SIGN, P-PICKLIST','P-ASSAY-UP (parse, match, index); P-ELN-SIGN (re-auth, hash, lock, PDF).','spec:§17.2','must','I4','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-061','functional','LabKey publish pipelines P-LK-SAMPLE, P-LK-ASSAY, P-LK-LIST, P-LK-STUDY','Driven by the outbox.','spec:§17.3','must','I6','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-062','functional','External data pipelines P-GEO-META, P-UNIPROT, P-BAG-SYNC, P-SPHN-TOKEN','P-GEO-META (accession metadata, no FASTQ); P-UNIPROT (accessions -> meta fields); P-BAG-SYNC (cron Wednesday, IDD-CSV); P-SPHN-TOKEN (manual, concept map only).','spec:§17.3','should','I7','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-063','functional','Operations pipelines','P-REINDEX, P-AUDIT-CKPT, P-RETENTION, P-KEY-ROTATE, P-RESTORE-DRILL.','spec:§17.4','must','I7','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-064','functional','LLMs act only through MCP tools','LLMs nutzen nur MCP-Tools. Keine Domain-Aktion ohne Tool.','spec:§18','must','I6','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-065','functional','Every LLM call emits an llm.invoke audit event','llm.invoke records model_id and request_id.','spec:§18','must','I6','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-066','functional','Assistant use cases','CSV intake mapping, SOP->template drafting, natural-language finder, free-slot lookup, queue prioritisation (read-only), ELN drafting, assay mismatch explanation, audit questions, LabKey error triage, GEO/PRIDE metadata.','spec:§18.1','should','I6','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-067','functional','Three assistant channels','UI chat against the local MCP; external assistants via API key on POST /mcp; batch workers on a service account writing into a review queue.','spec:§18.3','must','I6','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-068','functional','Aliquot fields that are not inherited from the parent','A sample type declares, per field, whether an aliquot inherits the parent value or carries its own. LabKey: ''Aliquots can have fields that are not inherited from the parent sample. Administrators can control which parent sample fields are inherited and which can be set independently for the sample and aliquot.'' (server 22.11 / LIMS 22.8). OSM spec 3 models AliquotLink with no inheritance policy, so today every aliquot silently inherits everything. Source: https://www.labkey.org/Documentation/Archive/22.11/wiki-page.view?name=releaseNotes2211','labkey:releaseNotes2211','should','I1','open','2026-08-26T17:19:31Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-069','functional','Sample expiry date, expiry indicator and expiring-sample reporting','Samples carry an expiry date; the UI marks an expired sample; a standing report lists samples nearing expiry. LabKey: ''Samples can have expiration dates, making it possible to track expiring inventories'' (23.3), ''See an indicator in the UI when a sample is expired'' (LIMS 23.6), ''Built in Sample Finder reports help you track expiring samples and those with low aliquot counts'' (23.7). OSM spec 3 has no expiry concept at all. Sources: https://www.labkey.org/Documentation/Archive/23.3/wiki-page.view?name=releaseNotes233 and https://www.labkey.org/Documentation/Archive/23.7/wiki-page.view?name=releaseNotes237','labkey:releaseNotes233','should','I1','open','2026-08-26T17:19:31Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-070','functional','Reason for change on a mutation, configurably required per operation class','A mutating operation may carry a free-text reason, stored on the audit event; an administrator configures per operation class whether the reason is required or optional. LabKey: ''The application can be configured to require reasons (previously called comments) for actions like deletion and storage changes'' (24.3), ''Users can better comply with regulations by entering a Reason for Update when editing sample, source or assay data'' (24.7), ''Storage Change Reasons - Provide a reason for sample moves, storage unit relocations, and storage definition edits, with each reason tracked in the audit log'' (LIMS 26.7). ADR-0003 defines the audit event with no reason field; adding it later means a migration over the hash-chained table, so it belongs in I0. Source: https://www.labkey.org/Documentation/Archive/24.3/wiki-page.view?name=releaseNotes243','labkey:releaseNotes243','must','I0','open','2026-08-26T17:19:31Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-071','functional','Identifying fields shown wherever a sample is referenced','An administrator nominates a bounded set of fields (LabKey caps it at six) that are displayed wherever a sample or source is picked from a list, hovered in a tooltip, or inherited by a derivative. LabKey: ''Customize which Identifying Fields are shown when users choose samples or sources from dropdowns'' (LIMS 24.11), ''Administrators can now set up to 6 identifying fields'' (LIMS 25.10), ''Ancestor-Sourced Identifying Fields on Derivatives'' (LIMS 26.7.3). A sample name alone is not enough to pick the right tube; OSM has no equivalent concept. Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-25.10','should','I1','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-072','functional','Amount and unit validated as a pair; amount may not be negative','Amount and unit are completed together or left empty together, and an amount may not be negative. LabKey: ''Amount and Unit fields are now enforced as a pair - both must be completed together or left empty'' (LIMS 25.10), ''Negative Amount Values Disallowed - Sample Manager now enforces that the Amounts field cannot have a negative value'' (LIMS 25.12). Cheap invariants that prevent a whole class of aliquot arithmetic defects; enforce at the database, not only at the boundary. Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-25.10','must','I1','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-073','functional','Check-out recorded as a queryable timestamped attribute of the sample','Beyond emitting a check-out event, the sample carries a CheckedOut timestamp that grids, the finder and the API can filter and sort on. LabKey: ''CheckedOut Column in Sample Grids - The CheckedOut date/time stamp is now an available column in sample grids'' (LIMS 25.7.8 ESR). OSM spec 5 models check-out as a pipeline and an audit event, which cannot answer ''what is out of the freezer right now'' without walking the trail. The same denormalisation serves the TTL reservation in FR-031. Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-25.7.8','should','I2','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-074','functional','Storage units identified by their own barcode, unique across the deployment','A terminal storage unit (box, plate, rack position) carries its own barcode, unique across the whole deployment, so a scan resolves a location as well as a sample. LabKey: ''Storage Unit Barcode Identification - Administrators can now configure terminal storage units to be identified by barcode, enabling globally unique identification across all projects on the server'' (LIMS 26.7). OSM spec 5 and PR-019 barcode samples only. Scanned storage-unit input is untrusted on exactly the same terms as scanned sample input (AGENTS.md section 3). Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-26.7','should','I2','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-075','functional','Storage and lineage operations available as workflow job tasks','A job template task can perform a storage or lineage operation directly, rather than instructing a human to go and do it elsewhere. LabKey: ''Workflow Storage Actions - Five new workflow actions let you add, check in, check out, move, and remove samples from storage directly within a workflow job'' (LIMS 26.5); ''Workflow Actions - Aliquot, derive, and pool samples directly within a workflow job'' (LIMS 26.4); ''New Workflow Action: Set Sample Status'' (LIMS 26.6); ''Derive Samples and Sources from Workflow Tasks'' (LIMS 26.9). OSM keeps storage pipelines (FR-058) and work pipelines (FR-059) strictly separate. Adopting this means a job task invokes a pipeline, which is a real architectural question: it must not become a second write path that bypasses the audit or the status machine. Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-26.5','should','I3','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-076','functional','Lineage relationships markable as required on a sample type','A sample type may declare that a given parent or source relationship is mandatory, so a sample of that type cannot be registered without it. LabKey: ''Lineage relationships can now be marked as required when creating or updating samples or sources'' (LIMS 24.10). OSM spec 3 makes the Source link optional everywhere; a derived cell line with no parent is a data-quality defect that nothing currently prevents. Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-24.10','should','I1','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-077','functional','ELN recall and return-for-changes, with a review timeline','The notebook state machine supports moving backwards: a reviewer returns a notebook for changes, an administrator recalls a submitted or approved notebook, and every such transition is visible on a review timeline. LabKey: ''More easily understand Notebook review history and changes including recalls, returns for changes, and more in the Review Timeline panel'' (24.7), ''Administrators can require a reason when a notebook is recalled'' (24.7), ''ELN Recall Email Notification - the author is emailed when an admin recalls a notebook'' (LIMS 25.11), ''Administrator Notebook Amendment - an admin may amend any notebook'' (LIMS 24.11). OSM FR-037 defines draft to review to approved to signed to locked with no reverse edge, so a notebook submitted in error is stuck. CON-004 still holds: a signed notebook stays immutable, and a recall of a signed notebook is an amendment, not an edit. Source: https://www.labkey.org/Documentation/Archive/24.7/wiki-page.view?name=releaseNotes247','labkey:releaseNotes247','should','I4','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-078','functional','Signature attestation text configurable per institution','The wording a signer attests to is configuration, not a constant, and the wording in force at signing time is stored with the signature. LabKey: ''Customize the certification language used during ELN signing to better align with your institution requirements'' (24.7 / LIMS 24.6). OSM spec 7 binds a content hash to the signer but never says what the signer is asserting. If the attestation text can change, the signature must record which text was shown, or the signature means nothing definite. Source: https://www.labkey.org/Documentation/Archive/24.7/wiki-page.view?name=releaseNotes247','labkey:releaseNotes247','should','I4','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-079','functional','Sample status usable as a filter on the lineage graph','The lineage view can be filtered by sample status, hiding matching nodes while preserving the edges between the ancestors and descendants that remain visible. LabKey: ''Lineage Filtering by Sample Status - filter the lineage graph by sample status, hiding nodes while keeping connections between visible ancestors and descendants'' (LIMS 26.7). A lineage graph over a long-lived project is mostly consumed samples; without this it is unreadable. Note the hard part is edge contraction, not filtering. Source: https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','labkey:limsSuiteReleaseNotes-26.7','could','I5','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-080','functional','Design authority separable from edit authority','The right to change a definition (sample type, source type, storage layout) is a distinct grant from the right to change the data inside it. LabKey: ''New Storage Editor and Storage Designer roles, allowing admins to assign different users the ability to manage freezer storage and manage sample and assay definitions'' with the explicit consequence that ''users with the Administrator and Editor role no longer have the ability to edit storage information unless they are granted one of these new storage roles'' (22.3), and ''New roles, Sample Type Designer and Source Designer'' (24.7, Community Edition). OSM spec 11 folds both into Project admin. Splitting them is the difference between a technician reorganising a freezer and a technician redefining what a freezer is. Source: https://www.labkey.org/Documentation/Archive/22.3/wiki-page.view?name=releaseNotes223','labkey:releaseNotes223','should','I0','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('FR-081','functional','Archive as an alternative to deletion for types, designs and templates','A definition that is no longer used can be archived: hidden from every picker and menu, while historic data that references it stays viewable and intact, and the archive is reversible. LabKey: ''Archive an assay design to hide it from Sample Manager data entry, but historic data can be viewed'' (21.11), ''Folders no longer in use can be archived'' (LIMS 24.11), ''Archive Workflow Job Templates - hide them from the template dropdown without affecting historical jobs, and restore them at any time'' (LIMS 26.8). OSM offers only delete, which every referential guard correctly refuses, so obsolete definitions accumulate in the UI forever. Source: https://www.labkey.org/Documentation/Archive/21.11/wiki-page.view?name=releaseNotes2111','labkey:releaseNotes2111','should','I1','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-001','nonfunctional','Freezer map renders 1000 boxes of 81 slots smoothly','1000 Boxen a 81 Slots ohne Ruckeln (~81000 slots).','spec:§5','must','I2','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-002','nonfunctional','Search P95 below 300 ms at one million samples','P95 < 300 ms bei 1e6 Proben.','spec:§8','must','I5','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-003','nonfunctional','API P95 latency below 200 ms','API P95 < 200 ms.','spec:§14','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-004','nonfunctional','100 concurrent users','100 parallele Nutzer.','spec:§14','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-005','nonfunctional','One million samples','1e6 Proben.','spec:§14','must','I0','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-006','nonfunctional','Point-in-time recovery for seven days','PITR 7 Tage.','spec:§14','must','I7','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-007','nonfunctional','Target WCAG 2.2 AA accessibility','WCAG 2.2 AA anstreben.','spec:§14','should','I1','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('NFR-008','nonfunctional','Box geometry supported to at least 50 rows by 50 columns','Row and column labelling, rendering and slot addressing must hold to at least 50 by 50. LabKey: ''The allowable box size for storage units has been increased to accommodate common slide boxes with up to 50 rows'' (23.11 / LIMS 23.8). This fixes a concrete bound on PR-016 acceptance criterion ''labels render correctly beyond 26 rows'', and on the NFR-001 render budget: 50 by 50 is 2500 slots in one box, thirty times the 81-slot box the budget assumes. Source: https://www.labkey.org/Documentation/Archive/23.11/wiki-page.view?name=releaseNotes2311','labkey:releaseNotes2311','should','I2','open','2026-08-26T17:19:32Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-001','prohibition','No SPHN/USB patient payload in OSM','Kein SPHN-/USB-Patientenpayload. Only tokenised identifiers may enter OSM.','spec:§1','must','','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-002','prohibition','Study PID only as an opaque token','Study-PID nur als Token. No re-identifiable patient identifier is stored.','spec:§4','must','','open','2026-08-26T08:31:36Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-003','prohibition','Strip PHI on publish','PHI beim Publish streichen.','spec:§16.2','must','','open','2026-08-26T08:31:37Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-004','prohibition','Do not use addWebPart against LabKey','Kein addWebPart. Portals are delivered as folder.xml zip archives.','spec:§16','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-005','prohibition','LLMs may never discard, ship or lock without a human','Discard/Ship/Lock ohne Mensch verboten.','spec:§18.2','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-006','prohibition','LLMs may never sign an ELN entry','ELN-Signatur verboten.','spec:§18.2','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-007','prohibition','LLMs may never change permissions','Rechte aendern verboten.','spec:§18.2','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-008','prohibition','No PHI in prompts','PHI in Prompts verboten.','spec:§18.2','must','','open','2026-08-26T08:31:38Z');
INSERT INTO requirements(id,kind,title,body,source,priority,iteration,status,created_at) VALUES('PRO-009','prohibition','No SQL or shell access outside the declared tools','SQL/Shell ausserhalb der Tools verboten.','spec:§18.2','must','','open','2026-08-26T08:31:38Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-001','LabKey CE premium boundary','CE ships the service interfaces for its premium capabilities with no implementation registered, and each degrades to a silent no-op rather than failing. InventoryService.get() returns null; SampleStatusService.isOperationPermitted() always returns true; ComplianceService passes PHI through; McpService is a Noop. Code that probes for these features will appear to work while enforcing nothing.','source','/root/scicore/server/modules/platform/api/src/org/labkey/api/{inventory,qc,compliance,mcp}/','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-002','Sample status enforcement in CE','Because no SampleStatusService provider is registered, DefaultSampleStatusService.isOperationPermitted() returns true unconditionally. LabKey CE therefore enforces no sample status rules at all: a sample marked Consumed can still be edited, aliquoted or derived. Status semantics must be owned by OSM.','source','/root/scicore/server/modules/platform/api/src/org/labkey/api/qc/SampleStatusService.java:84','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-003','Aliquot amounts are floats in LabKey','exp.Material stores StoredAmount as DOUBLE PRECISION and AliquotVolume as FLOAT. Repeated aliquot splitting accumulates floating-point error. OSM uses NUMERIC and Decimal end to end (ADR-0002) and accepts precision loss only at the publish boundary.','source','/root/scicore/server/modules/platform/experiment/resources/schemas/dbscripts/postgresql/exp-0.000-25.000.sql:323-368','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-004','Barcode field type is reachable in CE via the API','The Unique ID field type is blocked only in the bundled field-editor JavaScript, which checks isCommunityDistribution(). The server applies no gate, so creating a domain property with conceptURI http://www.labkey.org/types#storageUniqueId through property-createDomain.api yields DbSequence-backed auto-generated barcode values in CE. This makes barcode publishing to LabKey feasible without premium.','source','/root/scicore/build/deploy/modules/core/web/gen/domainDesigner.*.js and .../api/data/ColumnRenderPropertiesImpl.java:48','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-005','LabKey CE search cannot satisfy OSM spec 8','CE search is Lucene 10.5 with category filtering only. There is no faceting, no aggregation and no result counts per category, and sample categories are excluded from advanced search by default. OSM spec 8 requires facets over type, lineage, storage and assay thresholds at P95 below 300 ms across a million samples, so the finder must be built in OSM against PostgreSQL.','source','/root/scicore/server/modules/platform/search/src/org/labkey/search/model/LuceneSearchServiceImpl.java:1756-1766','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-006','LabKey CE authentication cannot satisfy OSM spec 2','CE ships only database-password and API-key authentication. There is no OIDC, SAML, CAS or LDAP authentication provider; OpenLdapSync only synchronises users and groups. OSM spec 2 requires OIDC, which OSM must therefore provide itself.','source','enumeration of AuthenticationProvider implementations under /root/scicore/server/modules','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-007','LabKey CE has no row-level security framework','Security is container plus role. ExpMaterialTableImpl.hasPermission delegates entirely to Container.hasPermission, and neither ExpMaterial nor ExpSampleType implements SecurableResource, so samples cannot carry ACLs. Restricting who sees which samples requires container partitioning. OSM spec 2 requires RLS, which PostgreSQL provides natively and OSM will use directly.','source','/root/scicore/server/modules/platform/experiment/src/org/labkey/experiment/api/ExpMaterialTableImpl.java:1844-1860','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-008','API key restriction roles are the right credential for the bridge','LabKey CE can mint an API key bound to a reduced role, limited to ReaderRole, AuthorRole, EditorWithoutDeleteRole or EditorRole. The labkey-bridge should authenticate with an EditorWithoutDelete-restricted key so a compromised bridge credential cannot delete published data. API keys must first be enabled in site settings, since allowApiKeys defaults to false.','source','/root/scicore/server/modules/platform/core/src/org/labkey/core/security/SecurityController.java:2305-2310','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-009','Correct LabKey action names','The bulk import action is query-import.api, not query-importData.api. There is no experiment-saveMaterials.api. experiment-deriveSamples is a FormViewAction serving a .view, while the programmatic endpoint is experiment-derive.api. Domain actions live under the property- controller which is implemented in the experiment module. Action naming follows @ActionNames when present, else the class name minus the Action suffix with only the first character lowercased.','source','/root/scicore/server/modules/platform/query/src/org/labkey/query/controllers/QueryController.java:4147 and SpringActionController.java:1084-1172','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-010','LabKey CE audit is detailed but not tamper-evident','Sample tables default to DETAILED audit behaviour and SampleTimelineEvent stores oldRecordMap and newRecordMap with a TransactionID, unconditionally and with no edition gate. But there is no hash chaining and no checkpoint, so alteration by anyone with database access is undetectable. OSM spec 9 requires detection, which is why the OSM trail is primary and the LabKey trail is a supplement (spec 16.1).','source','/root/scicore/server/modules/platform/experiment/src/org/labkey/experiment/samples/SampleTimelineAuditProvider.java and ExpMaterialTableImpl.java:2019','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-011','The laboratory module is prior art for a freezer model','The deployed LabDevKit laboratory module has laboratory.freezers and laboratory.samples with freezer, cane, box, box_row and box_column columns, plus freezer_space_summary and freezer_usage_by_box reporting queries. It is worth reading for layout ideas, but it is a separate schema from exp.material, has no slot-level exclusion constraint, no reservation TTL and no atomic move, so it cannot satisfy OSM spec 5.','source','/root/scicore/server/modules/LabDevKitModules/laboratory/resources/schemas/dbscripts/postgresql/laboratory-12.24-12.25.sql:40','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-012','File-based LabKey module layout','ModuleLoader reads <moduleDir>/config/module.properties and instantiates SimpleModule when ModuleClass is absent. Resources are queries/<schema>/<Query>.sql, views/<name>.html with .view.xml and .webpart.xml siblings, web/<module>/, and schemas/. Note that the deployed scicoreBrand module places module.properties at its root rather than under config/, so ModuleLoader ignores it - prior art not to copy.','source','/root/scicore/server/modules/platform/api/src/org/labkey/api/module/ModuleLoader.java:1126-1238','high','2026-08-26T08:41:57Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-013','MCP framework present in CE but inert','CE contains the MCP framework (McpService, McpContext, AbstractAgentAction) and tool definitions in CoreMcp, QueryMcp and SearchMcp, but no McpService implementation is registered and SearchModule has its registration commented out as not ready. There is no working MCP server in this build, so OSM spec 18 must be served by OSM''s own MCP server.','source','/root/scicore/server/modules/platform/api/src/org/labkey/api/mcp/ and SearchModule.java:136-141','high','2026-08-26T08:41:58Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-014','LabKey session and TLS conventions established by the user''s scripts','The user''s install scripts bootstrap a session by probing login-whoAmI.api with a cookie jar and scraping the CSRF field, falling back to login-loginApi.api with email and password. They deliberately avoid curl -f so 4xx bodies stay readable, avoid -L and set --max-redirs 0 because importFolder.post redirects to a host whose certificate does not match, and auto-enable -k for loopback HTTPS. Credentials come from LK_URL, LK_USER, LK_PASSWORD, LK_APIKEY, LK_CONTEXT and LK_INSECURE with matching flags and no prompting.','source','/root/install-labkey-uci-datasets.sh, /root/install-labkey-v940-evidence.sh','high','2026-08-26T08:41:58Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-015','addWebPart misbehaves on LabKey CE 26','The user''s scripts document that project-addWebPart.api is a FormViewAction whose getSuccessURL() calls addReturnUrl(), so omitting returnUrl throws a NullPointerException and floods labkey.log even when the web part was saved. OSM spec 16 independently forbids addWebPart and requires portals to be delivered as folder.xml archives, which avoids the problem entirely.','source','/root/install-labkey-uci-datasets.sh','high','2026-08-26T08:41:58Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-016','The LabKey release inventory is queryable, not scrapeable','The Previous Releases page builds its table client-side from the list lists.previousReleases in /Documentation and derives each release-notes URL as Archive/{major}.{minor}/wiki-page.view?name=releaseNotes{major}{minor}. Querying that list directly returns 59 rows and 59 distinct major.minor versions from 2.0 (2007) to 26.3 (2026). Two current releases, 26.7 and 26.11, are not in the list and are linked from the page navigation instead, giving 61 in total. The advertised URL pattern 404s for every release before 10.1; those pages exist as whatsnew{MM} (8.1 to 9.3) or whatsNew (2.1 to 2.3), and 2.0 has no release-notes page at all.','http','GET https://www.labkey.org/Documentation/query-selectRows.api?schemaName=lists&query.queryName=previousReleases&query.maxRows=-1','high','2026-08-26T17:22:04Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-017','LabKey marks premium content two different ways','The server release notes mark a premium feature with the star icon <span class="fa fa-star-o"></span>, whose printed legend reads ''The star symbol indicates a feature available in a Premium Edition of LabKey Server'' (widened from 22.11 to include Sample Manager and Biologics LIMS). The LIMS Suite release notes use no star at all - fa fa-star-o appears zero times - and instead badge each item with one or more of rnsm, rnpro, rnlims, rnent, rnbio, whose data-tip text names Sample Manager Starter, Sample Manager Professional, LIMS Starter, LIMS Enterprise and Biologics LIMS. Badges are cumulative upward, so the lowest badge is the first edition to provide the feature. An HTML comment at the top of the LIMS page transposes rnent and rnbio relative to the rendered data-tip text; the data-tip text was used.','web','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','high','2026-08-26T17:22:04Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-018','LabKey Community Edition lost sample-domain capability between 21.3 and 25.11','21.3 removed the Specimen Repository from all standard distributions including Community, with the explicit warning ''Do not upgrade a Community Edition if you want to continue using specimen as part of study'', and moved all non-PostgreSQL data sources to premium. 21.7 removed Specialty Assays from Community. 22.3 removed Panorama and MS2. 25.3 removed FreezerPro integration and SampleMinded integration. 25.11 removed the advanced folder-archive import options. Over the same period Community gained audit, security and API hygiene: forced detailed audit on Samples, Sources, Data Classes and Assay Data (25.11), per-folder See Audit Log Events and grid-view audit (26.3), role-restricted API keys (26.7). The direction is consistent with ADR-0001: CE is converging on a well-audited data platform and away from being a LIMS.','web','https://www.labkey.org/Documentation/Archive/21.3/wiki-page.view?name=releaseNotes213','high','2026-08-26T17:22:04Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-019','The Sample Manager paywall has two tiers, and the split is not where you would guess','The server release notes list Sample Manager features under one heading with no tier breakdown until 24.3, which invites the conclusion that the whole product sits at one price. The LIMS Suite badges show otherwise. Freezer management, check-in and check-out, picklists, aliquots, barcodes, sample status, the Sample Finder, storage roles and label printing are all Sample Manager Starter. The ELN, workflow jobs and templates, cross-project moves, in-app API keys and the required-reason configuration are Sample Manager Professional and above. Workflow-integrated storage actions are LIMS Starter and above. Plate campaigns are LIMS Enterprise and above. Reading the server notes alone over-states the paywall on storage and under-states it on workflow and the ELN.','web','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','high','2026-08-26T17:22:05Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-020','LabKey does not claim 21 CFR Part 11 in its release notes','Across 60 server release-notes pages and 83 LIMS release sections, the strings 21 CFR, Part 11, GxP and GMP appear exactly once, in LIMS 26.7.3 (July 2026), and there as a warning rather than a claim: a SAML Skip Reauthentication setting carries ''an inline warning that skipping may affect 21 CFR Part 11 eSignature requirements''. Electronic Signatures first shipped in 17.3 as signing a data grid snapshot with a reason; ELN signing gained email-and-password re-authentication only in 23.3 and required it on every signing event only in 24.3. Any Part 11 posture OSM adopts is OSM''s own, with no LabKey precedent to inherit or contradict.','web','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','high','2026-08-26T17:22:05Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-021','LabKey moved the workflow tables out of the sampleManagement schema','Release 26.3 records ''Workflow related tables have been moved from the sampleManagement schema to the workflow schema (introduced in version 26.1)''. It is listed under Client APIs and Development Notes, not as a breaking change. Any OSM query, report or publish path that names sampleManagement for workflow objects breaks silently on 26.1 and later. This is the concrete case that motivates CON-018.','web','https://www.labkey.org/Documentation/Archive/26.3/wiki-page.view?name=releaseNotes263','high','2026-08-26T17:22:05Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-022','LabKey removed cross-folder import in 26.7','LIMS 26.7 records ''Cross-Folder Import Removed - Importing samples, sources, or registry entries into a folder other than the current one is no longer supported.'' A publish bridge that batches rows destined for several containers into one query-import.api call against a single container will fail on 26.7 and later. The outbox worker must issue each import against the receiving container. 26.7 also removed the Derive Samples button from data grids and the ''Derive samples from this sample'' link from the sample details page; whether experiment-derive.api itself still works is not stated and is not assumed.','web','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','high','2026-08-26T17:22:05Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-023','LabKey 26.7 ships the MCP tool OSM prohibits','Server 26.7 adds MCP-Enabled SQL Access: ''AI agents connected to the MCP Server can now read and query data from any schema or table the authenticated user has permission to access, using the new executeSQL tool. Query results respect existing container and row-level permissions.'' The security bound is the credential the agent holds, not the tool surface - the position docs/gap-analysis.md already quotes LabKey as taking. The same release adds role-restricted API keys to Community Edition, described as ''a way to impose appropriate limits on AI agents, tools, and scripts'', which is the mechanism AGENTS.md section 3 already requires for the bridge key. OSM spec 18.2 and PRO-009 forbid exposing SQL or shell access outside the declared tools, so an executeSQL tool is not a capability OSM adopts under any configuration.','web','https://www.labkey.org/Documentation/wiki-page.view?name=releasenotes267','high','2026-08-26T17:22:05Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-024','The LIMS release notes are one page, not many','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes is a single consolidated page carrying 83 monthly release sections and 415 items, from 26.9 back to 20.3 plus 17.1 for the Biologics launch and four Extended Support Releases. All 369 hrefs in its body and navigation were parsed; none points to a per-version LIMS release-notes page, and no /limshelp/Archive/ URLs exist. Its cadence is monthly against the server''s four-monthly, which is why the same feature carries two different version numbers depending on which notes you read. The page also has real defects: there is no 24.3 section, nothing between 17.1 and 20.3, unfinished internal editing notes published verbatim in 24.4, several items truncated at a colon, and 21.1''s only entry is the bare string ''Freezer Management''.','web','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes','high','2026-08-26T17:22:05Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-025','LabKey marks the Community boundary three different ways, and one is invisible to a nav crawl','1. A page-level badge on /Documentation pages: <b class="bold">Premium Feature</b> followed by one of five wordings - ''Available with all Premium Editions of LabKey Server'' (Starter and up), ''Available in the Professional and Enterprise Editions'', ''Available in the Enterprise Edition'', ''Also available as an Add-on to the Starter Edition'', and ''Available upon request with all Premium Editions''. The wording is load-bearing and must be read, not skimmed. 2. An inline star, <span class="fa fa-star-o"></span> followed by (Premium Feature), for individual items inside a list on an otherwise Community page. The navigation tree contains zero stars, so a nav-only crawl finds none of them. 3. A blue ''Available in:'' callout on every /limshelp page, whose complete chip vocabulary is exactly SM Starter, SM Professional, LIMS Starter, LIMS Enterprise, Biologics LIMS. There is no Community chip anywhere in the limshelp wiki. A page may carry a second badge lower down for a feature within it that starts at a higher tier.','web','https://www.labkey.org/Documentation/wiki-page.view?name=compliance','high','2026-08-26T17:28:47Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-026','Sample management is a separate product, not a premium feature of LabKey Server','The freezer, the workflow queue, the notebook, the picklist, the sample finder, the sample timeline and the sample status UI live in the /limshelp container, are badged against Sample Manager and LIMS editions rather than LabKey Server editions, and no tier of that product is free. What LabKey Server''s own premium editions add on top is infrastructure - ETL, SSO, PHI enforcement, compliance logging, external data sources, MCP - and not sample management. A 265-page documentation sweep did not overturn a single conclusion in docs/gap-analysis.md; it confirmed ADR-0001''s ''there is no CE substrate to extend'' from LabKey''s own documentation rather than from its build files.','web','https://www.labkey.org/limshelp/wiki-page.view?name=smFreezer','high','2026-08-26T17:28:47Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-027','LabKey documents no point-in-time recovery and no restore drill, at any price','dbBackup, backupRestore, backupChecklist, backupScenarios and enterprisePlan all carry no premium badge and no star: LabKey''s documented backup story is pg_dump and pg_restore guidance, free to everybody. The only edition-linked backup item found anywhere in the sweep is on labkey.com''s Sample Manager pricing page - Backup Retention 90 days for SM Starter and 180 days for SM Professional - which is a hosted-service SLA rather than a software feature. OSM''s NFR-006 (seven-day PITR) and PR-038 (a demonstrated restore) are therefore stricter than the commercial product, with prior art in PostgreSQL and none in LabKey.','web','https://www.labkey.org/Documentation/wiki-page.view?name=dbBackup','high','2026-08-26T17:28:47Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-028','A LabKey CE folder archive cannot carry storage or sample status definitions','The folder export page marks ''Inventory locations and items'' as a premium feature: ''If any freezers have been defined in Sample Manager in this container, you will see this checkbox to include freezer definitions and storage information in the export.'' Server 22.3 records the same for status: ''Sample status types and values are exported and imported with folder archives, when the sampleManagement module is present'', and that module is premium. Consequence for the bridge (PR-031, PR-032): OSM''s storage model and its eight-status lifecycle have no downstream representation in LabKey CE at all and are OSM-only by construction. Manual folder export and import themselves are unbadged and free, so PRO-004''s folder-archive route for portals is available.','web','https://www.labkey.org/Documentation/wiki-page.view?name=importExportFolder','high','2026-08-26T17:28:47Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-029','LabKey CE has database logins and nothing else','The authentication module page states that ''The ability to add other authentication methods and to define multiple configurations of each method is available with all Premium Editions of LabKey Server.'' LDAP, LDAP synchronisation, SAML, CAS as client, CAS as identity provider, Duo and TOTP each carry the same badge. Community Edition therefore has database logins only. OSM''s OIDC requirement (FR-013, PR-006) cannot lean on LabKey for any part of identity, which is consistent with ADR-0001 but worth stating: the bridge authenticates to LabKey with an API key (ADR-0008), and LabKey never authenticates an OSM user.','web','https://www.labkey.org/Documentation/wiki-page.view?name=authenticationModule','high','2026-08-26T17:28:47Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-030','The Sample Manager tiering is not where you would guess','Freezer management, check-in and check-out, storage roles, aliquots, picklists, barcodes, sample status, the Sample Finder, sample expiry and label printing are all SM Starter, the cheapest paid tier. Workflow jobs, job templates, the ELN, folders and data partitioning, cross-folder moves, in-app API keys, BarTender setup and the required-reason configuration are SM Professional. Job template ACTIONS - the guided buttons that make a template do something rather than merely list steps - custom import templates and in-app charts are LIMS Starter. Plate campaigns, media and the bioregistry are LIMS Enterprise and Biologics LIMS, and 21 CFR Part 11 electronic signatures sit there too, two tiers above the ELN itself. OSM''s specification spans all four tiers.','web','https://www.labkey.org/limshelp/wiki-page.view?name=jobTemplate','high','2026-08-26T17:28:47Z');
INSERT INTO research(id,topic,finding,evidence_kind,evidence_ref,confidence,created_at) VALUES('RF-031','LabKey''s own sources disagree about editions in eight places','1. The ELN is scoped on two different axes: labkey.com''s SDMS matrix marks it Professional and Enterprise of LabKey Server, the doc badges scope it to SM Professional and above of a different product line. 2. labkey.com''s matrix gives Enterprise LabKey Server the Professional tier of Sample Manager, which no doc page states. 3. 21 CFR Part 11 is claimed for Enterprise LabKey Server on labkey.com and for LIMS Enterprise and Biologics LIMS on limshelp/enterpriseGov. 4. S3, REDCap, CDISC and Spotfire: the docs are more permissive than the matrix, adding ''Also available as an Add-on to the Starter Edition''. 5. The MCP Server appears nowhere on the matrix and its doc badge is the only one in the corpus that says ''LabKey SDMS'' rather than ''LabKey Server''. 6. The Sample Manager pricing table shows only Starter and Professional, both paid, and lists HIPAA Compliance and Software Validation as paid add-ons that no labkey.org page mentions. 7. Dataset QC states are unbadged while assay QC states are premium. 8. limshelp/uniqueStorageIds (SM Starter+) and Documentation/uniqueStorageIds (all Premium Editions) document the same barcode field under two edition vocabularies - and it works in CE anyway. Where a labkey.org badge and the labkey.com matrix disagree, neither is authoritative; the build files and the source are (docs/labkey-ce-ground-truth.md).','web','https://www.labkey.com/products-services/labkey-server/#editions','medium','2026-08-26T17:28:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0001','OSM Is The System Of Record And LabKey CE Is A Downstream Publish Target','accepted','The brief framed the work as a Sample Manager for LabKey CE; the specification says OSM is independent of LabKey products, is not a LabKey UI clone, and that LabKey is downstream. LabKey CE has no storage, workflow or ELN substrate to extend.','Build OSM standalone with its own PostgreSQL database, services, API and UI. A labkey-bridge publishes downstream.','Positive: OSM owns RLS, the eight-status lifecycle, slot constraints, the audit chain and its own performance targets. Negative: sample types, lineage and aliquots are reimplemented despite existing in exp; two systems to operate; publish must be idempotent.','Build as a LabKey module (contradicts the spec, no RLS, audit not immutable); hybrid with samples in exp.material (makes same-transaction auditing impossible).','','2026-08-26T08:42:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0002','Python, FastAPI And PostgreSQL As The Implementation Stack','accepted','The spec fixes PostgreSQL with RLS and requires OpenAPI and an MCP server. The host already provides PostgreSQL 18.6 and Python 3.11.','Python with FastAPI, SQLAlchemy 2.x and Alembic; React with TypeScript for the UI as a separate API client.','Positive: OpenAPI and boundary validation come from the type model; Decimal avoids float drift in aliquot arithmetic; the connection stays visible for RLS. Negative: async transaction scoping must be enforced by a unit-of-work helper and tested, because the same-transaction audit rule fails silently otherwise.','Java with Spring Boot (heaviest toolchain, weaker MCP SDK); TypeScript with NestJS (ORM fights RLS, float semantics hazardous for amounts).','','2026-08-26T08:42:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0003','Tamper-Evident Audit Written Inside The Domain Transaction','accepted','Spec 2 requires every write audited in the same transaction and spec 9 requires an append-only SHA-256 chain with a daily checkpoint. A naive chain forks under concurrency.','Database triggers guarantee completeness, the unit-of-work additionally emits semantic domain events, and a PostgreSQL advisory lock serialises hash and sequence assignment so the chain is linear.','Positive: no write escapes the trail including a direct psql session; tampering is detectable; the auditor role is read-only by grant rather than by convention. Negative: the advisory lock serialises hash assignment and must be load-tested against the 100-concurrent-user target.','Application-level helper only (completeness depends on discipline); triggers only (cannot express business events like notebook.signed at the altitude the export needs).','','2026-08-26T08:42:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0004','Slot Occupancy Enforced By A Database Constraint','accepted','Spec 5 requires one sample per slot, atomic moves, TTL reservations and HTTP 409 on conflict. Check-then-write races, and a race here breaks the freezer map''s 1:1 correspondence with physical reality.','Model occupancy and reservation as one slot_assignment row with a tstzrange, enforced by EXCLUDE USING gist (slot_id WITH =, valid_during WITH &&) via btree_gist.','Positive: double occupancy is impossible; TTL expiry is a property of the data rather than a sweeper job that can crash silently; slot history is a byproduct feeding the sample timeline and audit export. Negative: btree_gist must be installed by a migration that fails loudly; GiST cost must be measured against the 81000-slot target.','Application-level check-then-write (races, disqualifying); partial unique index on occupancy (does not cover reservations, so the invariant lives in two places).','','2026-08-26T08:42:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0005','Transactional Outbox For LabKey Publishing','accepted','Spec 3 defines PublishOutbox and spec 16.2 requires the bridge to drain a queue, store failures with the HTTP body, and use osm_id for idempotency. LabKey can be down or slow.','The domain transaction inserts an osm_publish_queue row alongside the domain write; a worker drains it with SELECT FOR UPDATE SKIP LOCKED and upserts on osm_id.','Positive: a publish can never be lost because intent and write share a commit; LabKey downtime only grows the queue; publish lag is one observable metric. Negative: eventual consistency, so the UI must show publish state explicitly rather than implying LabKey already has the sample.','Synchronous publish in the transaction (LabKey downtime becomes OSM downtime); post-commit async job (a crash between commit and enqueue loses the publish silently).','','2026-08-26T08:42:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0006','The MCP Server Is A Thin Adapter Over The REST API','accepted','Spec 10 says MCP tools are REST semantics, spec 8 says the UI goes through the same surface, and spec 18.3 requires that prompt injection in an SOP PDF cannot unlock extra tools. A second door into the domain would drift from the first.','Each MCP tool is a thin translation onto a REST call authenticated as the agent''s principal, so there is exactly one authorisation implementation.','Positive: an agent structurally cannot exceed the role it authenticates as; the tool allowlist is bound to the session at authentication time and is not derived from document content. Negative: one loopback HTTP hop per tool call; errors need translation without leaking data the principal cannot see.','MCP with direct in-process domain access (two authorisation paths that will drift); shared service layer with two transports (sharing is enforced only by review, and agent-specific prohibitions have no natural home).','','2026-08-26T08:42:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0007','Project Memory Is A Git-Tracked SQL Dump','accepted','The project runs across many sessions that each start without prior context. Durable knowledge must be both machine-queryable and reviewable.','Track .sdd/memory.sql as the deterministic source of truth and treat .sdd/memory.db as a derived, git-ignored artifact rebuilt on demand.','Positive: every knowledge change is a reviewable text diff; merge conflicts are ordinary text conflicts; the CLI enforces id patterns, foreign keys and enums. Negative: contributors must use the CLI, and the dump must be regenerated on every write - handled by regenerating automatically and failing tools/memory.py check when the tracked copy has drifted.','Commit the binary db (no reviewable diff, unresolvable merges, not byte-stable); markdown only (no cross-cutting queries, no constraints, traceability degrades to unvalidated links).','','2026-08-26T08:42:47Z');
INSERT INTO decisions(id,title,status,context,decision,consequences,alternatives,supersedes,created_at) VALUES('ADR-0008','Credentials Come Exclusively From The Environment','accepted','No secret may enter the repository. The user''s existing scripts already establish LK_URL, LK_USER, LK_PASSWORD, LK_APIKEY, LK_CONTEXT and LK_INSECURE, but build-labkey-community.sh also shows the failure mode to avoid: defaulting a password to a real value that works, so nobody notices.','Every credential is read from the environment with no defaults, no config files and no prompting; a missing required variable aborts with a message naming it. Credentials pass to subprocesses through the environment, never as command-line arguments.','Positive: committing a secret would require deliberately writing one into a file; CI and secret managers work unchanged; the repository has no git remote until GITHUB_TOKEN is supplied. Negative: variables must be re-exported per shell, and are visible to other processes of the same user - accepted deliberately for a single-user research server.','Git-ignored config file (one git add -f from disaster, persists on disk); a secret manager (right for production, disproportionate here, and not foreclosed since the environment is the interface it injects into).','','2026-08-26T08:42:47Z');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-001','registry','Sample types with custom fields','SM: name, description, naming pattern, lineage and storage settings, unlimited custom fields, per-field aliquot editability. CE: exp.MaterialSource plus property-createDomain.api with kind SampleSet.','yes','native','low','labkey.org/limshelp createSampleType; /root/scicore .../api/exp/api/ExpSampleType.java','OSM reimplements per ADR-0001 but the LabKey publish mapping is direct.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-002','registry','Naming patterns and ID generation','Tokens genId, sampleCount, daily/weekly/monthly/yearlySampleCount, randomId, batchRandomId, now, withCounter, column and lineage refs; modifiers defaultValue, minValue, number, date.','yes','native','low','labkey.org/limshelp sampleIDs; /root/scicore .../api/data/NameGenerator.java SubstitutionValue','CE has the full NameGenerator. OSM needs an equivalent pattern engine for spec 4 type designer.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-003','registry','Sources / parent entities (Data Classes)','SM presents Data Classes as Sources with Overview/Lineage/Samples/Assays/Jobs tabs. CE has exp.DataClasses but no Sources UI.','yes','partial','low','labkey.org/Documentation dataClass; labkey.org/limshelp sources (LIMS badge)','Publish maps OSM Source to a LabKey Data Class.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-004','registry','Lineage and derivation','SM: parent aliases, derive/pool, 5-generation lineage graph, Distance column, up to 20 ancestor levels in grid views. CE: exp.Edge, exp.MaterialAncestors, experiment-lineage.api, experiment-derive.api.','yes','native','medium','labkey.org/limshelp deriveSamples; /root/scicore .../experiment/lineage/ and ExperimentController.java:7297,5957','CE has the graph engine; the Run Builder UI is premium. OSM needs its own lineage store and timeline.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-005','registry','Aliquots with amount and unit tracking','SM: aliquot UI, sub-aliquots, pooling, aliquot naming with withCounter and zero padding, calculated total/available amount and aliquot count. CE: the exp.Material columns exist and NameGenerator supports AliquotedFrom, but the aliquot UI is LIMS-only and the aliquot naming option cannot be set from the LabKey Server interface.','yes','partial','medium','labkey.org/limshelp aliquots and aliquotIDs; V-004','CE stores amounts as DOUBLE PRECISION. OSM uses NUMERIC (RF-003).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-006','registry','Sample status lifecycle','SM: three status types Available, Consumed, Locked, with admin-defined named statuses inside each, colour-coded. CE: exp.SampleStateType has the three types but SampleStatusService has no provider, so isOperationPermitted() always returns true and no status rule is enforced at all.','yes','absent','medium','labkey.org/limshelp sampleStatus; V-002; V-008; RF-002','OSM spec 3 requires eight statuses: Registered, Available, Reserved, In Process, Consumed, Locked, Discarded, Shipped. Neither SM nor CE provides these.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-007','storage','Freezer and storage hierarchy','SM: physical location levels Site/Building/Room/Other, storage systems, non-terminal Shelf/Rack/Canister, terminal Bag/Box/Cane/Plate/Tube Rack. CE: no inventory schema at all; InventoryService.get() returns null.','yes','absent','high','labkey.org/limshelp createFreezer, freezerLocation; V-001; V-008','OSM spec 5 requires five levels site/building/room, device, rack/drawer, box/plate, slot. The deployed laboratory module has prior art but no slot constraint (RF-011).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-008','storage','Box and plate layouts','SM: Box up to 50x25, Plate up to 25x25 with 6x4/8x6/12x8/24x16 built-ins, Tube Rack, Bag, Cane. Position labelling columns-and-rows (A-1 default, AA/AB beyond 26 rows) or numbered position.','yes','absent','medium','labkey.org/limshelp manageUnits','OSM spec 5 requires rows x cols with an A1 origin.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-009','storage','Check-in, check-out and move','SM: check-out reserves the slot, mandatory reason in Professional, check-in captures Amount Used and auto-increments Freeze/Thaw Count; fill order and fill direction on placement.','yes','absent','high','labkey.org/limshelp checkout, storeFreezer','OSM spec 5 additionally requires atomicity, HTTP 409 on conflict and TTL reservation, none of which SM documents.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-010','storage','TTL slot reservation','SM reserves a slot for the duration of a check-out but documents no time-to-live expiry. CE has nothing.','no','absent','medium','labkey.org/limshelp checkout; V-001','OSM spec 5 requires TTL reservation. This is a capability OSM has beyond the commercial product (ADR-0004 makes expiry a property of the data).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-011','storage','Capacity and free-space views','SM has no discrete find-empty-slots feature; free space is emergent from per-level spaces-available counts, per-section notes during placement and a capacity bar. Layout maps show occupied dots and shade checked-out cells.','partial','absent','medium','labkey.org/limshelp manageFreezer, freezerDetails','OSM spec 18.1 wants an assistant find_empty tool, which implies a real free-slot query rather than an emergent count.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-012','storage','Box move as an atomic batch','SM documents moving samples within storage but not an all-or-nothing box relocation.','no','absent','medium','labkey.org/limshelp storeFreezer; OSM spec 5, 17.1 P-BOXMOVE','Beyond the commercial product.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-013','registry','Barcodes and unique IDs','SM: UniqueID field type generating 9+ digit zero-padded strings, unique application-wide, read-only on import; plus a scannable flag for pre-existing barcodes. CE: the server supports the storageUniqueId concept URI with a DbSequence, but the field editor JavaScript refuses the type for community distributions.','yes','partial','low','labkey.org/limshelp uniqueStorageIds; V-011; RF-004','Reachable in CE through property-createDomain.api, so the publish path can create real barcode fields.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-014','registry','Label printing','SM: BarTender integration only, requiring a BarTender Automation licence and .btw templates; printing is SM Starter but the admin setup page excludes SM Starter. No ZPL or Zebra support is documented anywhere.','partial','absent','medium','labkey.org/limshelp barTender, setupBarTender','OSM spec 15 lists a ZPL printer as an open point. Direct ZPL would be a capability beyond the commercial product.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-015','workflow','Jobs, tasks and templates','SM Professional and up: ordered tasks, assignment to users or groups, admin-only templates with custom fields and attachments, per-task actions for sample, source and storage operations, archivable templates.','yes','absent','high','labkey.org/limshelp workflow, jobTemplate, manageJobs; V-001','OSM spec 6 additionally requires optimistic locking on complete and T-1/T+1 escalation.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-016','workflow','Queue views and notifications','SM: Jobs List, Templates, Your Job Queue, Your Tracked Jobs; in-app bell in all editions, email notifications from SM Professional with Workflow and Notebook categories.','yes','absent','medium','labkey.org/limshelp manageJobs, notifications','OSM spec 6 requires my tasks, active jobs and a board.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-017','workflow','Due-date escalation','SM notifies on task readiness, job initiation, reactivation and comments, but documents no T-1 and T+1 due-date escalation.','no','absent','low','labkey.org/limshelp notifications; OSM spec 6','Beyond the commercial product.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-018','eln','Electronic lab notebook','SM Professional and up: dashboard with For You filters, references to samples, sources, assay runs, jobs and other notebooks via @ mention, templates, PDF export via Puppeteer.','yes','absent','high','labkey.org/limshelp sampleELN, elnReference, elnDash; V-001','Not in CE at all; the labbook module is absent.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-019','eln','Review, signing and locking','SM: submit with reviewers and an optional deadline, re-authentication on both submission and approval, approve / request changes / defer, recall with reason, approved notebooks locked, customisable certification text, review history recording which auth method signed. A Skip Reauthentication option for SAML carries an explicit warning that it may not meet 21 CFR Part 11.','yes','absent','high','labkey.org/SampleManagerHelp elnReview, elnAmend','OSM spec 7 requires draft/review/approved/signed/locked with re-auth and a JSON hash. The hash binding is beyond what SM documents.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-020','search','Faceted sample finder','SM Sample Finder: facets on sample, parent-sample and source properties in all editions, plus assay result data in Professional; Equals All Of across up to 10 ancestors; criteria persist between sessions; named saved searches. CE: Lucene with category filtering only, no faceting, no aggregation, and sample categories excluded from advanced search.','yes','absent','high','labkey.org/limshelp sampleFinder; V-010; RF-005','OSM spec 8 adds storage and assay-threshold facets and a P95 below 300 ms at 1e6 samples.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-021','registry','Picklists','SM: private or shared, may mix sample types, usable in jobs, assays, storage operations and label printing, exportable. Deliberately not recorded in sample timelines and not included in folder archive exports.','yes','absent','low','labkey.org/limshelp samplePicklist','OSM spec 4 and 17.2 P-PICKLIST require picklists that can start a job.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-022','assay','Assay data linked to samples','SM Professional and up: every assay design must include a Sample-type field, file drag-drop with preview, background processing above 100 kb, optional workflow task association, results on the sample detail Assays tab. CE: standard and general assays are present; specialty assays (NAb, ELISpot, ELISA, Luminex, Flow, MS2) and assay QC states are premium.','yes','partial','medium','labkey.org/limshelp defineAssaySchema, importAssay; labkey.org/Documentation assayQCconfig','This server does deploy the commonAssays modules (elisa, elispot, luminex, nab, flow, ms2) despite them not being in community.gradle (V-007).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-023','audit','Sample timeline','SM: per-sample graphical history of sample, assay, job and storage events with actor and timestamp, Excel export. CE: SampleTimelineEvent audit provider registered unconditionally with oldRecordMap and newRecordMap, DETAILED by default.','yes','native','low','labkey.org/limshelp sampleTimeline; V-005; V-018; RF-010','One of the few LIMS-layer capabilities CE genuinely provides.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-024','audit','Tamper-evident hash-chained audit','Neither SM nor CE chains audit events. CE stores detailed before/after maps and refuses routine purging, but a database administrator can alter rows undetectably. SM offers 21 CFR Part 11 support through ELN signing rather than through a tamper-evident trail.','no','absent','high','V-018; RF-010; labkey.org/limshelp audits','OSM spec 9 requires a SHA-256 chain with a daily checkpoint. This is a capability beyond the commercial product (ADR-0003).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-025','audit','Electronic signatures for 21 CFR Part 11','SM: ELN signing is the practical Part 11 path from SM Professional. True grid-level Signed Snapshots are Enterprise-only, and Enterprise Data Governance bundles LDAP plus electronic signatures at LIMS Enterprise. CE has none.','partial','absent','medium','labkey.org/Documentation eSignatures; labkey.org/limshelp enterpriseGov','OSM spec 7 puts signature at I4, available to every deployment.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-026','security','Row-level security','Neither SM nor CE has row-level security on samples. CE security is container plus role; ExpMaterialTableImpl.hasPermission delegates entirely to Container.hasPermission and samples cannot carry ACLs. Restricting visibility requires container partitioning.','no','absent','high','V-009; RF-007','OSM spec 2 requires PostgreSQL RLS. Beyond the commercial product.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-027','security','PHI handling and compliance','SM: the compliance and PHI module is Enterprise-only. CE: the PHI enum and PhiColumnBehavior exist and the FilteredTable call sites are wired, but no ComplianceService is registered so nothing is masked. PHI tags survive export and import and provide no protection.','partial','absent','medium','V-016; RF-001; labkey.org/Documentation compliance','OSM spec 1 and 16.2 forbid PHI outright and require stripping on publish, which sidesteps the problem rather than solving it.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-028','security','SSO: OIDC, SAML, CAS, LDAP','SM: LDAP, SAML and CAS arrive at LIMS Enterprise. CE: only database password and API keys; no OIDC, SAML, CAS or LDAP authentication provider exists, and OpenLdapSync only synchronises users and groups.','partial','absent','medium','V-012; RF-006; labkey.org/limshelp limsEnterprise','OSM spec 2 requires OIDC in I0.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-029','api','Client APIs and API keys','SM: API access is an SM Professional entitlement. CE: the full HTTP API and JavaScript, Java, Python, R, SAS and Perl clients are available, and API keys support restriction roles (Reader, Author, EditorWithoutDelete, Editor) though allowApiKeys defaults to false.','partial','native','low','V-013; RF-008; labkey.org/Documentation viewApis','The bridge authenticates with an EditorWithoutDelete-restricted key.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-030','llm','MCP server','SM: the LabKey MCP Server is Professional/Enterprise SDMS and LIMS Starter and up, read-only (schema browsing, SQL drafting and validation, and from 26.7 executeSQL). LabKey states plainly that what limits the agent is the API key, not the server. CE: the MCP framework and tool definitions exist but no McpService implementation is registered and the search registration is commented out as not ready.','partial','absent','high','V-008; RF-013; labkey.org/Documentation mcp','OSM spec 10 and 18 require write tools with confirm plus scope, an llm.invoke audit event and a session-bound allowlist. Substantially beyond the commercial product (ADR-0006).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-031','labkey','Publish to LabKey CE','Not a commercial SM feature; SM is the store rather than a publisher. CE provides everything needed: core-createContainer.api, property-createDomain.api, query-import.api, query-insertRows.api, experiment-derive.api, assay-importRun.api, wiki-saveWiki.api and WebDAV.','no','native','medium','RF-009; RF-014; /root/install-labkey-uci-datasets.sh','OSM spec 16 and 17.3. Uses folder.xml archives rather than addWebPart (PRO-004, RF-015).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-032','ops','Cross-folder moves with preserved lineage','SM Professional and up: moving samples, sources and assay runs across folders is audited, appears in the timeline and preserves lineage. CE has query-moveRows.api but no application-level guarantees.','yes','partial','low','labkey.org/limshelp crossFolder','Maps onto OSM project retention and the spec 16.2 project-to-folder mapping.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-033','ui','Storage map export','SM produces a printable Excel storage map matching the physical layout.','yes','absent','low','labkey.org/limshelp manageStored','Useful precedent for the OSM freezer map print view.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-034','ops','Open source and self-hostable at zero licence cost','Commercial SM starts at USD 6540/yr for 5 users (SM Starter) and reaches USD 59400/yr (Biologics LIMS). Every capability OSM targets - storage, aliquot UI, status, barcodes, picklists, finder, workflow, ELN - sits behind that paywall. LabKey CE itself is Apache 2.0 but ships none of the LIMS application layer.','no','native','none','labkey.com/pricing; labkey.org/limshelp limsSuite','OSM spec 1: Apache-2.0 / CC-BY-4.0. This is the project''s reason for existing.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-035','registry','Aliquot fields not inherited from the parent','Per-field control of whether an aliquot inherits the parent value or carries its own; the administrator sets the policy per sample type.','yes','absent','low','https://www.labkey.org/Documentation/Archive/22.11/wiki-page.view?name=releaseNotes2211 ; LIMS 22.8','FR-068, PR-042. Server 22.11 / LIMS 22.8, SM Starter and above.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-036','registry','Sample expiry dates and expiring-inventory reporting','An expiry date system field, an expired indicator in the UI, and built-in reports for soon-expiring stock and low aliquot counts.','yes','partial','low','https://www.labkey.org/limshelp/wiki-page.view?name=sampleExpiration ; server 23.3 added exp.material.materialExpDate','FR-069, PR-043. CE has the materialExpDate column since 23.3; the indicator and the reports are SM Starter and above.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-037','registry','Identifying fields','Up to six administrator-chosen fields displayed wherever a sample or source is picked, hovered, or inherited by a derivative.','yes','absent','low','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes (24.11, 24.12, 25.10, 26.3, 26.7.3)','FR-071, PR-044. SM Starter and above. A sample name alone is not enough to pick the right tube.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-038','registry','Required lineage relationships','A sample type may declare a named parent or source relationship mandatory, refusing registration without it.','yes','absent','low','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes (24.10)','FR-076, PR-046. SM Starter and above.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-039','registry','Archive instead of delete for definitions','A sample type, assay design, job template or folder can be archived: hidden from every picker while historic data stays readable, and restorable.','yes','absent','low','https://www.labkey.org/Documentation/Archive/21.11/wiki-page.view?name=releaseNotes2111 ; LIMS 24.11, 26.8','FR-081, PR-047. Every referential guard correctly refuses deletion, so without archiving obsolete definitions accumulate forever.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-040','registry','Amount and unit paired validation','Amount and unit are completed together or left empty together, and an amount may not be negative.','yes','absent','none','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes (25.10, 25.12)','FR-072, PR-045. CE stores amounts as DOUBLE PRECISION with no such constraint. OSM enforces at the database, per ADR-0002.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-041','storage','Check-out as a queryable sample attribute','A CheckedOut date/time stamp on the sample itself, filterable and sortable in grids, rather than only an audit event.','yes','absent','low','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes (25.7.8 ESR)','FR-073, PR-048. The same denormalisation carries the FR-031 TTL reservation.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-042','storage','Storage unit identified by barcode','Terminal storage units carry their own barcode, globally unique across every project on the server, so a scan resolves a location as well as a sample.','yes','absent','medium','https://www.labkey.org/limshelp/wiki-page.view?name=createFreezer ; LIMS 26.7','FR-074, PR-049. Scanned storage input is untrusted on the same terms as scanned sample input.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-043','storage','Freeze/thaw cycle counting','Check-in and check-out increment a per-sample freeze/thaw counter; updates may carry a comment.','yes','absent','low','https://www.labkey.org/limshelp/wiki-page.view?name=checkout ; server 21.3, 22.3','FLAGGED AS QUESTIONABLE SCOPE. Real cryobiology need, cheap to add, and absent from the OSM specification. See docs/labkey-release-notes-survey.md section 7. Ask the specification owner.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-044','workflow','Storage and lineage operations as workflow tasks','Job template tasks that add, check in, check out, move or remove samples from storage, and that aliquot, derive, pool or set the status of samples, within the job.','yes','absent','medium','https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes (26.4, 26.5, 26.6, 26.9)','FR-075, PR-050. LIMS Starter and above; the guided template actions sit one tier above job templates themselves. The design constraint is that a task must invoke the existing pipeline and never become a second write path.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-045','workflow','Structured user-defined fields on workflow jobs','Searchable, filterable, standardised custom fields on a job, for structured work requests and billing codes.','yes','absent','medium','https://www.labkey.org/Documentation/Archive/22.11/wiki-page.view?name=releaseNotes2211 ; LIMS 22.9','FLAGGED AS QUESTIONABLE SCOPE. Turns a job into a request form; OSM spec 6 does not. SM Professional and above.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-046','eln','Notebook recall, return for changes and review timeline','Reverse edges in the notebook state machine, an author notification on recall, a configurably required recall reason, and a timeline showing the review history.','yes','absent','medium','https://www.labkey.org/Documentation/Archive/24.7/wiki-page.view?name=releaseNotes247 ; LIMS 24.5, 25.11','FR-077, PR-051. OSM FR-037 has no reverse edge, so a notebook submitted in error is stuck. SM Professional and above.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-047','eln','Configurable signature attestation text','The certification language a signer attests to is configuration rather than a constant.','yes','absent','low','https://www.labkey.org/Documentation/Archive/24.7/wiki-page.view?name=releaseNotes247 ; LIMS 24.6','FR-078, PR-052. OSM spec 7 binds a content hash to the signer but never says what the signer asserts. If the text can change, the signature must record which text was shown.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-048','eln','Notebook PDF export via a headless browser service','Signed, human-readable PDF export of a notebook, which LabKey implements with a separate Puppeteer (headless Chrome) service.','yes','absent','medium','https://www.labkey.org/limshelp/wiki-page.view?name=puppeteer','PR-026. Rendering a legally meaningful PDF is not a library call; OSM inherits the same operational cost. SM Professional and above.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-049','audit','Reason for change on a mutation','A mutating operation may carry a free-text reason stored on the audit event, and an administrator configures per operation class whether it is required.','yes','absent','low','https://www.labkey.org/limshelp/wiki-page.view?name=audits ; server 24.3, 24.7 ; LIMS 24.2, 24.4, 25.6, 26.7','FR-070, PR-040. Scheduled in I0 because ADR-0003 hash-chains the audit table and adding a field later is a migration nobody wants. SM Professional and above.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-050','audit','Audit log retention and maintenance','Site administrators set an audit retention time from three months to seven years; older records are deleted nightly, optionally exported to text first.','yes','absent','none','https://www.labkey.org/Documentation/wiki-page.view?name=auditLogMaintenance','DELIBERATELY NOT ADOPTED. ADR-0003 chains audit events, so deleting one breaks the chain. Recorded because the direction is instructive: LabKey''s premium audit feature is the ability to throw audit away. Moved Professional to Starter in 26.3.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-051','audit','Read-access auditing (compliance query logging)','Logs which users saw which data, including the SQL run, the subject identifiers returned and the PHI columns touched.','yes','absent','medium','https://www.labkey.org/Documentation/wiki-page.view?name=complianceLogging','FLAGGED. OSM audits every write (FR-011) and no read. Defensible for a system holding no PHI, but it is a position rather than an oversight and should be stated. Enterprise Edition only.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-052','security','Design authority separate from edit authority','Storage Editor and Storage Designer, and Sample Type Designer and Source Designer: the right to change a definition is a distinct grant from the right to change the data inside it.','yes','partial','low','https://www.labkey.org/limshelp/wiki-page.view?name=freezerRoles ; server 22.3, 24.7','FR-080, PR-041. The Sample Type Designer and Source Designer roles reached Community Edition in 24.7; the storage roles did not, because storage did not.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-053','security','Restricted rendering of inaccessible lineage nodes','An entity the caller may not read is shown as restricted, preserving graph structure without exposing detail; the earlier approach removed access and identifiers outright.','yes','absent','medium','https://www.labkey.org/Documentation/Archive/23.7/wiki-page.view?name=releaseNotes237 ; LIMS 26.2','CON-015, PR-053. LabKey took both available positions three years apart. OSM must choose one deliberately and test the lineage, timeline and ELN reference paths, not only the sample grid.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-054','security','Multi-factor authentication','TOTP and Duo second factors, plus a Require Secondary Authentication role that applies them selectively.','yes','absent','medium','https://www.labkey.org/Documentation/wiki-page.view?name=configureTotpTwoFactor','FLAGGED. OSM has no MFA requirement, which is a gap worth raising for a system whose signatures are meant to be binding (FR-038). All Premium Editions.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-055','security','Malware scanning of uploads','ClamAV scanning of uploads, attachments, pipeline and WebDAV content.','yes','absent','medium','https://www.labkey.org/Documentation/wiki-page.view?name=virusChecking','FLAGGED. OSM accepts CSV uploads and ELN attachments (PR-014, PR-024). AGENTS.md section 3 bounds size, validates content type and neutralises formula injection, and says nothing about malware. All Premium Editions.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-056','ops','Access recertification and project locking','Lock a project against non-administrators, and enforce a periodic review of project permissions after which the project expires.','yes','absent','medium','https://www.labkey.org/Documentation/wiki-page.view?name=projectLock','FLAGGED. Identity governance rather than sample management; OSM spec 11 does not ask for it. Enterprise Edition. Defer to an ADR if an auditor asks.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-057','labkey','Storage in a folder archive','Freezer definitions and stored-item locations are included in a folder archive only with a premium distribution.','yes','absent','none','https://www.labkey.org/Documentation/wiki-page.view?name=importExportFolder','CONSEQUENCE, NOT A GAP. A CE folder archive cannot carry storage, so OSM''s storage model has no downstream representation at all and is OSM-only by construction. State it in the FRD for PR-031. Sample status values have the same problem: they round-trip only when the premium sampleManagement module is present (server 22.3).');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-058','llm','MCP server with an executeSQL tool','AI agents on the MCP Server read and query any schema or table the authenticated user may access, through an executeSQL tool; results respect container and row-level permissions.','yes','absent','none','https://www.labkey.org/Documentation/wiki-page.view?name=mcp ; https://www.labkey.org/Documentation/wiki-page.view?name=releasenotes267','DELIBERATELY NOT ADOPTED. PRO-009 forbids SQL or shell access outside the declared tools, and CON-012 binds the tool allowlist to the session. LabKey''s bound is the credential; OSM''s is the tool surface. Professional and Enterprise Editions of LabKey SDMS.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-059','ops','Point-in-time recovery and a demonstrated restore drill','Recovery to any moment in a defined window, proven by a scheduled restore into a scratch database.','no','absent','medium','https://www.labkey.org/Documentation/wiki-page.view?name=dbBackup ; https://www.labkey.org/Documentation/wiki-page.view?name=backupRestore','NFR-006, PR-036, PR-038. LabKey''s backup pages carry no premium badge at all and document pg_dump and pg_restore guidance only: no PITR and no restore drill at any price. OSM''s requirement is stricter than the commercial product''s, with prior art in PostgreSQL and none in LabKey.');
INSERT INTO features(id,area,name,detail,commercial,ce_support,gap,evidence,notes) VALUES('FEAT-060','registry','Cross-folder moves of audited objects','Move samples, sources, assay runs, workflow jobs and notebooks between folders, individually or across several destinations at once.','yes','absent','medium','https://www.labkey.org/limshelp/wiki-page.view?name=crossFolder ; server 23.7, 24.7','FLAGGED. Moving an audited object between security scopes is a design question, not a convenience: what happens to its audit history, its lineage across the boundary, and its RLS predicate. Not in the OSM specification. Recommend an ADR before anyone implements it. SM Professional and above.');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-001',1,'LabKey client library and verification harness','A reusable, credential-safe Python client for the LabKey HTTP API, plus the harness that records environment facts into the memory database. Everything that later talks to LabKey builds on this, and every future claim about LabKey behaviour is verified through it.','Client reads LK_URL, LK_USER, LK_PASSWORD, LK_APIKEY, LK_CONTEXT and LK_INSECURE from the environment and refuses to run when neither an API key nor a user/password pair is present, naming the missing variable | No credential appears in any log line, exception message or command line | Session bootstrap probes login-whoAmI.api, falls back to login-loginApi.api, and captures the CSRF token for mutating calls | TLS verification is skipped only for loopback hosts unless LK_INSECURE is set explicitly | Redirects are not followed and 4xx bodies are preserved and surfaced | A LabKeyError carries the action, status code and response body | scripts/verify_labkey.py runs read-only checks and writes verification rows via tools/memory.py | Unit tests cover credential resolution, CSRF handling, TLS policy and error surfacing without touching the network | An integration test marked labkey runs against the live server and passes','','I0','M','pr-001-labkey-client','review','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-002',2,'Python project skeleton, tooling and quality gates','pyproject with pinned dependencies, ruff, mypy, pytest with coverage, and a single make target that runs every gate. Establishes the deterministic rebuild the project promises.','pyproject.toml declares the project and pins every dependency through a lock file | ruff, mypy and pytest all run clean on the existing tree | Coverage threshold is enforced and fails the build below it | make check runs lint, types, tests and tools/memory.py check | A fresh clone reproduces the same resolved dependency set','PR-001','I0','S','pr-002-python-skeleton','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-003',3,'PostgreSQL schema bootstrap and migrations','Alembic wired up, the btree_gist extension installed, database roles for application and auditor created with least privilege, and an idempotent bootstrap script.','alembic upgrade head creates the schema from empty and is idempotent | The btree_gist migration fails loudly if the extension cannot be created rather than continuing | An osm_app role holds INSERT and SELECT on audit tables and no UPDATE or DELETE | An osm_auditor role holds SELECT only | scripts/bootstrap_db.py is safe to re-run and never drops data without an explicit flag | Downgrade is defined for every migration | Tests run against a throwaway database created and dropped by the fixture','PR-002','I0','M','pr-003-db-bootstrap','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-004',4,'Tamper-evident audit hash chain','Implements ADR-0003: triggers for completeness, semantic domain events for meaning, advisory-lock serialisation for chain linearity, canonical JSON hashing.','Every insert, update and delete on an audited table produces an audit row, verified by writing directly through psql and observing the event | The unit-of-work helper emits a semantic domain event in the same transaction as the domain write | Canonical JSON serialisation is byte-stable and covered by a test with unicode, nested objects and numeric edge cases | prev_hash links every event; the genesis event uses the all-zero digest | A concurrency test with parallel writers produces a single linear chain with no forks and no duplicate sequence numbers | Chain verification detects an altered row and a deleted row | actor_type records human, mcp or system','PR-003','I0','M','pr-004-audit-chain','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-005',5,'Audit checkpoint, verification and export','Daily checkpoint anchoring the chain head, a verification routine that walks back only to the last checkpoint, and a trail export for an entity or a time range.','A checkpoint stores the head hash and sequence number and is signed | Verification walks back to the most recent checkpoint rather than to genesis | Verification of a tampered range fails and names the first broken link | Trail export produces a stable, reviewable format for one entity and for a time range | The auditor role can run verification and export and nothing else','PR-004','I0','S','pr-005-audit-checkpoint','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-006',6,'Identity: users, roles, sessions and OIDC','The seven-role model from spec 11, session handling, and OIDC login. LabKey CE has no OIDC provider, so OSM supplies its own.','The seven roles Reader, Technician, Scientist, Reviewer, Storage/Workflow admin, Project admin and Auditor exist with the permissions spec 11 assigns | Authorisation is evaluated in one place and every route declares the permission it needs | OIDC login completes against a configured provider and creates or links a local principal | Re-authentication is available as a distinct operation, for use by ELN signing | Auditor is read-only and cannot reach any mutating route | Role checks are covered by tests that assert denial, not only success','PR-003','I0','M','pr-006-identity','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-007',7,'API keys and service accounts','Machine credentials with scoped privileges, for the bridge, batch workers and external assistants.','An API key can be minted with a role no broader than its owner holds | Only a hash of the key is stored | Keys carry an expiry and can be revoked, and revocation takes effect immediately | Key use is audited with the key identifier and never the key itself | A service account cannot escalate its own privileges','PR-006','I0','S','pr-007-api-keys','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-008',8,'FastAPI application skeleton, OpenAPI and RLS plumbing','The HTTP surface: routing, a consistent error model, request validation at the boundary, generated OpenAPI, and the per-request PostgreSQL session variables that RLS policies read.','OpenAPI is generated and served, and covers every declared route | Every request body is validated at the boundary and a validation failure returns a structured 4xx naming the field | Errors follow one documented shape and never leak stack traces or SQL | Each request sets the RLS session variables for the authenticated principal, and a test proves a request cannot read another project''s rows | Slot and uniqueness conflicts map to 409 | Health and readiness endpoints exist and do not require authentication','PR-006','I0','M','pr-008-api-skeleton','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-009',9,'Projects and sample type designer','Project entities with retention, and sample types carrying a naming pattern, custom field definitions and permitted statuses (spec 3, spec 4).','A project admin can define a sample type with custom fields and a naming pattern | Field definitions are validated, and reserved names are rejected with a clear message | A sample type in use cannot have a field removed without an explicit migration path | Project retention is stored and surfaced | Every change emits an audit event','PR-008','I1','M','pr-009-projects-types','todo','2026-08-26T08:47:51Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-010',10,'Name expression engine','The pattern language for sample and aliquot identifiers, modelled on the tokens LabKey CE supports so that published names round-trip.','Supports counters scoped per type and per day, week, month and year, random ids, dates and field references | Supports an aliquot pattern deriving from the parent name with a counter, a configurable separator and zero padding | Counter allocation is atomic under concurrency and never yields a duplicate | An invalid pattern is rejected at definition time with the position of the error | Generated names are unique within their scope, enforced by a database constraint','PR-009','I1','M','pr-010-name-expressions','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-011',11,'Sources and sample registration','Source entities with a human id and metadata, and the P-INTAKE pipeline: type, id, source, slot and label (spec 17.1).','A technician can register a sample against a type and an optional source | human_id is unique per project and enforced by a constraint | Study PID is accepted only as an opaque token and never as a re-identifiable value | Registration follows the pipeline shape trigger, validation, action, audit | A registration that fails validation leaves no partial state | Amounts are stored as NUMERIC and arithmetic uses Decimal throughout','PR-010','I1','M','pr-011-sources-samples','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-012',12,'Sample status lifecycle state machine','The eight statuses from spec 3 and the transitions between them, enforced server-side. Neither LabKey CE nor the commercial product enforces status rules.','The statuses Registered, Available, Reserved, In Process, Consumed, Locked, Discarded and Shipped exist | Only declared transitions are permitted and an illegal transition returns a 409 naming the current and requested status | A Consumed sample cannot be aliquoted or derived | A Locked sample rejects every mutation except adding it to a picklist | Every transition emits an audit event carrying the old and new status | Transition rules are covered by a test per edge, including the denials','PR-011','I1','S','pr-012-status-lifecycle','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-013',13,'Aliquots, derivation and lineage','P-ALIQUOT and P-DERIVE (spec 17.1): amount splitting, child creation, and the lineage graph. This is the I1 acceptance gate.','Creating an aliquot decrements the parent available amount and the arithmetic is exact, with a test proving no drift over a thousand successive splits | Sub-aliquots are supported and the root sample is tracked | Derivation creates a sample of a different type carrying a parent link | Pooling many parents into one child is supported | The lineage graph can be queried by ancestor and descendant with a bounded depth | A cycle cannot be created and an attempt returns a 409 | Deleting a sample with descendants is refused','PR-012','I1','M','pr-013-aliquots-lineage','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-014',14,'CSV bulk intake','Bulk sample registration from a delimited file, with strict server-side validation and an all-or-nothing outcome.','A file is parsed, validated and either fully applied or fully rejected | Every rejected row is reported with its line number and the reason | Column names are matched safely and no column name can influence SQL construction | Formula injection is neutralised so a cell beginning with an equals or at sign cannot execute on export | Upload size and row count are bounded and exceeding either returns a clear 4xx | The file content type is validated rather than trusted | A malformed or hostile file cannot crash the import or consume unbounded memory','PR-011','I1','M','pr-014-csv-intake','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-015',15,'Sample timeline','The chronological view of everything that happened to a sample (spec 4), assembled from the audit trail.','The timeline shows registration, updates, status changes, storage events, job events and assay events with actor and timestamp | Events are ordered deterministically including within the same timestamp | The timeline is readable by anyone who can read the sample and by nobody else | Export produces a stable format','PR-013','I1','S','pr-015-timeline','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-016',16,'Storage hierarchy model','The five levels of spec 5: site/building/room, device, rack/drawer, box/plate and slot, with geometry and capacity.','The hierarchy can be created, renamed and reorganised, and a node cannot be its own ancestor | Box geometry is rows by columns with an A1 origin, and labels render correctly beyond 26 rows | Capacity is derived from geometry rather than stored separately | A node holding samples cannot be deleted | Structural changes require the storage admin role | Creating a 1000-box hierarchy completes within a bounded time recorded in the test','PR-008','I2','M','pr-016-storage-hierarchy','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-017',17,'Slot assignment, check-in, check-out and move','Implements ADR-0004: the exclusion constraint and the atomic P-CHECKIN, P-CHECKOUT and move operations. This is the I2 acceptance gate.','The exclusion constraint rejects two overlapping assignments on one slot, proven by a concurrent test with parallel writers | A conflict returns 409 naming the slot, and the occupying sample only when the caller may read it | Check-in, check-out and move are atomic and a failure leaves both slots unchanged | Check-out sets the sample to Reserved and frees the slot per spec 17.1 | Every operation emits an audit event and appears in the sample timeline | Slot history is queryable and shows what occupied a slot over time','PR-016','I2','L','pr-017-slot-assignment','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-018',18,'Atomic box move and TTL reservations','P-BOXMOVE and the time-limited reservation from spec 5, both capabilities the commercial product does not offer.','Moving a box relocates every contained sample in one transaction, and a conflict on any slot rolls back the whole move | A reservation carries an expiry and stops conflicting automatically at that instant with no sweeper job involved | An expired reservation is visibly distinct from an active one in queries | Reserving an occupied slot returns 409 | A test advances time and proves the slot becomes free without any background process running','PR-017','I2','M','pr-018-boxmove-reservation','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-019',19,'Barcodes and label generation','Barcode allocation for samples and storage units, and label rendering including direct ZPL, which the commercial product does not support.','Barcode allocation is atomic and never yields a duplicate, enforced by a database constraint | Scanned input is treated as untrusted: length-bounded, character-validated and never interpolated into a query | A barcode that does not resolve returns 404 rather than a lookup error that reveals whether the id exists in another project | Label templates render to ZPL and to PDF | A label template cannot embed executable content','PR-011','I2','M','pr-019-barcodes-labels','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-020',20,'Freezer map user interface','The visual map from spec 12, meeting the NFR-001 rendering target.','A box of 81 slots renders with occupancy and status colouring | Navigation between hierarchy levels preserves context via a breadcrumb | 1000 boxes of 81 slots render and scroll without stutter, measured and recorded | Drag-to-move issues one atomic move and shows the 409 clearly when it conflicts | The view meets WCAG 2.2 AA for contrast and keyboard navigation | The map is usable without a mouse','PR-017','I2','L','pr-020-freezer-map-ui','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-021',21,'Job templates','Reusable SOP skeletons defined without samples (spec 6), with ordered tasks and per-task actions.','A template declares ordered tasks with optional custom fields | A template contains no sample references | Templates can be copied and archived, and an archived template is hidden from new jobs while history is preserved | A template referenced by a job cannot be deleted | Only a workflow admin may create or edit templates','PR-008','I3','M','pr-021-job-templates','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-022',22,'Jobs, tasks and optimistic locking','P-JOB-START and P-JOB-TASK (spec 17.2): instantiate a template against samples or a picklist, and complete tasks safely under concurrency.','Starting a job binds samples to a template and materialises its tasks | Completing a task requires the version the client last read, and a stale completion returns 409 rather than overwriting | A concurrent test proves two simultaneous completions produce exactly one success | Task completion advances the job and emits an audit event | A blocked task escalates per P-JOB-BLOCK | Tasks can be assigned to a user or a group','PR-021','I3','M','pr-022-jobs-tasks','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-023',23,'Queue views, escalation and notification','The three queue views from spec 6, T-1 and T+1 due-date escalation, and the notify service.','My tasks, active jobs and the board each return correctly scoped results and respect row-level security | Escalation fires once at T-1 and once at T+1 and is idempotent under retry | Notification delivery failures are recorded and retried rather than dropped | A user can configure which notifications they receive | No notification body contains data the recipient may not read','PR-022','I3','M','pr-023-queue-escalation','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-024',24,'Notebooks and the ELN state machine','P-ELN-DRAFT (spec 17.2) and the draft to review to approved to signed to locked machine from spec 7.','Only forward transitions are permitted and a backward transition returns 409 | Content is stored with a canonical representation suitable for hashing | Notebooks reference samples, sources, jobs and assay runs, and a reference to an unreadable entity is not rendered | Templates produce a starting draft | Rich content is sanitised on the server, and no stored content can execute script when rendered','PR-008','I4','M','pr-024-eln-notebooks','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-025',25,'ELN review workflow','P-ELN-REVIEW (spec 17.2): submission to a reviewer queue, approval, change requests and recall.','Submission places the notebook in the reviewer queue with an optional deadline | Only a Reviewer may approve | An author may recall with a stated reason before approval | Requesting changes returns the notebook to draft and records the reason | Every review action is audited with the actor and the timestamp','PR-024','I4','S','pr-025-eln-review','todo','2026-08-26T08:47:52Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-026',26,'ELN signature, locking and PDF','P-ELN-SIGN (spec 17.2): re-authentication, a JSON content hash bound to the signer, immutability and PDF export. This is the I4 acceptance gate.','Signing requires a fresh re-authentication and a stale session is refused | The signature binds the canonical JSON hash of the content to the signer identity and timestamp | A signed notebook rejects every mutation at the database level, not only in application code | Tampering with a signed notebook is detectable by recomputing the hash | An amendment creates a new revision and leaves the signed version intact and readable | The PDF renders deterministically and is stored for publication to LabKey | An LLM cannot reach this operation at all, since it is not exposed as an MCP tool','PR-025','I4','L','pr-026-eln-signature','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-027',27,'Faceted finder','The finder from spec 8: facets over type, lineage, storage and assay thresholds, meeting NFR-002.','Facets cover sample properties, parent and ancestor properties, storage location and assay thresholds | Facet counts are returned alongside results | A query filtering an ancestor property returns correct results across multiple generations | P95 stays below 300 ms at one million samples, measured by a benchmark that fails the build when exceeded | Filter expressions are parsed into a typed structure and never concatenated into SQL | A hostile filter expression cannot read data outside the caller''s scope','PR-013','I5','L','pr-027-finder','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-028',28,'Picklists','Named working sets of samples that can start a job (spec 4, P-PICKLIST).','A picklist may mix sample types and may be private or shared | A picklist can start a job and can drive a storage operation | Membership respects row-level security so a shared picklist never exposes a sample the viewer cannot read | Removing a sample from a picklist does not affect the sample','PR-027','I5','S','pr-028-picklists','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-029',29,'Row-level security enforcement','PostgreSQL RLS policies on every domain table, the I5 acceptance gate. Neither LabKey CE nor the commercial product has this.','Every domain table carries an RLS policy and a test proves a direct database session as osm_app cannot read another project''s rows | Policies are driven by the session variables set per request | A missing session variable denies access rather than permitting it | The auditor role can read the trail and no domain table | A new table without a policy fails a schema test, so the protection cannot be forgotten','PR-008','I5','M','pr-029-rls','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-030',30,'Publish outbox','Implements ADR-0005: the transactional queue that decouples OSM writes from LabKey publishing.','An outbox row commits in the same transaction as the domain write, proven by a test that kills the process after commit and observes the row present | PHI is stripped when the row is built, not at publish time, so no payload containing PHI is ever queued | The worker claims rows with SELECT FOR UPDATE SKIP LOCKED and two workers never publish the same row | A failed publish stores the HTTP status and body and is retried with capped exponential backoff | A row exhausting its attempts remains FAILED and is never silently dropped | The age of the oldest pending row is exposed as a metric','PR-013','I6','M','pr-030-publish-outbox','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-031',31,'LabKey bridge: sample publishing (P-LK-SAMPLE)','The first publish pipeline: create the container and sample type domain in LabKey CE, then import samples idempotently.','The bridge authenticates with an API key restricted to EditorWithoutDelete | A sample type domain is created in LabKey with the OSM fields plus osm_id and a barcode field using the storageUniqueId concept URI | Re-publishing the same sample upserts on osm_id and creates no duplicate, proven by a test that publishes twice | A response lost in transit followed by a retry converges rather than duplicating | Lineage is published as lookups and storage_path as a plain string, with the map remaining in OSM | Publishing uses query-import.api, not the non-existent query-importData.api | A LabKey 4xx is captured with its body and surfaced in the FAILED row | The pipeline never calls addWebPart','PR-030,PR-001','I6','L','pr-031-bridge-samples','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-032',32,'LabKey bridge: assays, lists, studies and portals','P-LK-ASSAY, P-LK-LIST and P-LK-STUDY, plus folder.xml portal delivery instead of addWebPart.','Assay runs publish with their sample links and an accompanying wiki page | Catalogs publish as lists via folder.xml archives | A study publish without both a subject and a timepoint is rejected with a clear reason rather than partially applied | Portals are delivered as folder.xml zip archives and addWebPart is never called | Jobs publish as a read-model list | An ELN PDF is uploaded to the LabKey files area under eln','PR-031','I6','M','pr-032-bridge-assay-list-study','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-033',33,'MCP server: read tools','Implements ADR-0006: the MCP transport as an HTTP client of the REST API, starting with read-only tools.','Each tool is a thin translation onto a REST call authenticated as the agent principal, with no direct domain access | An agent cannot read anything the same principal could not read over REST, proven by a test with a restricted principal | Every invocation emits llm.invoke carrying model_id and request_id | The tool allowlist is bound to the session at authentication time and is not derived from any content the agent reads | A document instructing the agent to use an unlisted tool has no effect, covered by an injection test | Errors are translated without leaking data the principal cannot see','PR-008','I6','M','pr-033-mcp-read','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-034',34,'MCP server: guarded write tools','Write tools with the confirm and scope requirements of spec 10, and the absolute prohibitions of spec 18.2.','A destructive tool requires both confirm=true and the osm.admin.write scope, and confirm is a distinct explicit argument | Discard, ship, lock, ELN signing and permission changes are not present in the tool list at all | Every agent-initiated write is audited with actor_type set to mcp and correlated with its llm.invoke event | At most one unsafe write chain is permitted per turn and a second is refused | A test asserts that each prohibited operation has no corresponding tool, so the prohibition cannot be weakened by adding one later','PR-033','I6','M','pr-034-mcp-write','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-035',35,'Assistant channels and RAG guardrails','The three channels of spec 18.3 and the use cases of spec 18.1, with a corpus restricted to SOPs, templates and schemas.','UI chat, external assistants on an API key, and batch workers on a service account all work and are distinguishable in the audit | Batch worker results land in a review queue and are never applied directly | The RAG corpus is restricted at index time to SOPs, templates and schemas, and PHI-bearing ELN content and USB files are excluded rather than filtered at query time | An intake assistant proposes a CSV mapping and creates nothing until confirmed | HUGGINGFACE_API_KEY and HUGGINGFACE_MODEL_ID are read from the environment and their absence produces a clear message rather than a failure at call time','PR-034','I6','M','pr-035-assistants','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-036',36,'Operations pipelines','P-REINDEX, P-AUDIT-CKPT, P-RETENTION, P-KEY-ROTATE and P-RESTORE-DRILL from spec 17.4.','Each pipeline is idempotent and safe to re-run | Retention honours the per-project retention setting and refuses to delete anything referenced by a signed notebook | Key rotation re-signs checkpoints without invalidating the existing chain | The restore drill restores into a scratch database and verifies the audit chain end to end | A failed pipeline run is recorded with its cause and never reported as success','PR-029','I7','M','pr-036-ops-pipelines','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-037',37,'Performance benchmarks against the non-functional targets','Benchmarks that can fail, covering the spec 14 and spec 8 targets rather than asserting them.','API P95 below 200 ms at 100 concurrent users, measured and failing the build when exceeded | Search P95 below 300 ms at one million samples | The freezer map renders 1000 boxes of 81 slots within the recorded budget | The audit advisory lock is shown not to be the bottleneck at 100 concurrent writers, or the finding is recorded and ADR-0003 revisited | A seeded dataset of one million samples is reproducible from a script','PR-027','I7','M','pr-037-benchmarks','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-038',38,'Deployment, backup and runbook','The I7 acceptance gate: a runbook that a second person could follow.','Point-in-time recovery is configured and a seven-day restore is demonstrated | Deployment is scripted, idempotent and produces a deterministic result | The runbook covers start, stop, backup, restore, key rotation, publish-queue triage and audit verification | Every environment variable is documented with its purpose and whether it is required | A restore drill is scheduled and its last result is observable','PR-036','I7','M','pr-038-runbook','todo','2026-08-26T08:47:53Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-039',39,'Verify the LabKey 26.x claims this survey could not confirm','docs/labkey-release-notes-survey.md section 6.4 lists five behavioural questions the release notes raise and cannot answer. Close each against the running server through the PR-001 client and record the result, including the failures. A doc-grade belief that nobody checks is exactly the failure mode AGENTS.md section 2 exists to prevent.','experiment-derive.api is called against the live server and the result recorded, establishing whether the 26.7 removal of the Derive Samples button also removed the API|A client-API write passing an audit-suppressing parameter is attempted and the observed audit level recorded, establishing whether the 25.11 audit floor rejects or ignores it|The 22.11 Storage API is called in CE and the result recorded, against the ground-truth finding that InventoryService.get() returns null|The 23.11 per-field uniqueness constraint is created and violated, establishing whether it is enforced by the database or by application code|Whether the LIMS and SDMS MCP servers are one subsystem or two is resolved from source under /root/scicore, or recorded as unresolved|Every probe writes a verifications row through tools/memory.py, and a fail is recorded rather than retried until convenient|docs/labkey-ce-ground-truth.md is updated with whatever the probes establish','PR-001','I0','S','pr-039-labkey-26x-verification','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-040',40,'Reason for change on every mutation','FR-070. A mutating operation may carry a reason, stored on the audit event; an administrator configures per operation class whether it is required. Scheduled in I0 because ADR-0003 hash-chains the audit table, and adding a field to a chained table later is a migration nobody wants.','The audit event carries an optional reason, included in the canonical JSON that is hashed|An administrator can require a reason per operation class, and a required reason that is missing returns a structured 4xx naming the operation|The reason is bounded in length and neutralised for formula injection on export, per the CSV rules in AGENTS.md section 3|A reason is never inferred, defaulted or auto-generated: absent means absent|Tests cover the required case, the optional case and the refusal','PR-004','I0','S','pr-040-change-reason','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-041',41,'Design authority separate from edit authority','FR-080. Split the right to change a definition from the right to change the data inside it, as LabKey did in 22.3 for storage and in 24.7 for sample and source types. Extends the seven-role model of spec 11 rather than replacing it.','A principal can hold edit rights over sample data without holding the right to change a sample type definition, and the denial is tested|A principal can hold edit rights over storage contents without holding the right to change the storage hierarchy, and the denial is tested|Granting design authority is itself audited|The existing seven roles keep their spec 11 permissions; the new grants are additive|specs/adr/ gains a decision record if this changes the role model rather than extending it','PR-006','I0','S','pr-041-designer-roles','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-042',42,'Aliquot field inheritance policy','FR-068. Per-field control of whether an aliquot inherits the parent value or carries its own.','A sample type declares, per field, inherited or independent|Creating an aliquot copies inherited fields and leaves independent fields unset|Changing a parent inherited field does not retroactively rewrite existing aliquots, and the chosen semantics are documented|Changing the policy on a type in use is either refused or migrated explicitly, never silently|Every policy change is audited','PR-013','I1','S','pr-042-aliquot-inheritance','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-043',43,'Sample expiry dates and expiring-inventory reporting','FR-069. An expiry date on a sample, an expired indicator, and a standing query for samples nearing expiry.','A sample carries an optional expiry date and an expired sample is identifiable in one query|Expiry is a fact, not a status: it does not by itself drive a lifecycle transition, and the reasoning is recorded|A report lists samples expiring within a caller-supplied window|Expiry participates in the finder as a facet|Time zone handling is explicit and tested at a boundary','PR-011','I1','S','pr-043-sample-expiry','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-044',44,'Identifying fields','FR-071. A bounded, administrator-chosen set of fields shown wherever a sample or source is referenced.','An administrator nominates identifying fields per type, and the count is bounded with the bound enforced server-side|Identifying fields appear in every reference context: pickers, tooltips, lineage nodes and derivative creation|A derivative shows identifying field values sourced from its ancestor correctly|A field marked PHI can never be an identifying field, enforced server-side and tested|Removing a field from a type removes it from the identifying set atomically','PR-009','I1','S','pr-044-identifying-fields','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-045',45,'Amount and unit pairing invariants','FR-072. Amount and unit are set together or not at all, and an amount may not be negative. Enforced by database constraint, not only at the boundary.','A check constraint rejects an amount without a unit and a unit without an amount|A check constraint rejects a negative amount|The constraints are proven by writing directly through psql, not only through the API|Aliquot arithmetic cannot drive a parent amount negative, and the attempt returns a 409|Decimal is used throughout, per the ADR-0002 convention','PR-011','I1','XS','pr-045-amount-invariants','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-046',46,'Required lineage relationships','FR-076. A sample type may declare a parent or source relationship mandatory.','A sample type can mark a named parent or source relationship required|Registering a sample of that type without the relationship is refused with a message naming the relationship|Bulk intake reports the violation per row with its line number|Making a relationship required on a type with existing violating rows is refused, naming the count|The rule is enforced server-side and covered by a denial test','PR-013','I1','XS','pr-046-required-lineage','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-047',47,'Archive instead of delete for types, designs and templates','FR-081. Hide an obsolete definition from every picker while keeping historic data readable, reversibly.','A sample type, source type or job template can be archived and restored|An archived definition appears in no picker, menu or creation path|Existing data referencing an archived definition stays readable and its detail pages still render|Archiving is audited, and so is restoring|An archived definition cannot be used to create anything new, enforced server-side','PR-009','I1','S','pr-047-archive-definitions','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-048',48,'Check-out state as a queryable sample attribute','FR-073. Denormalise check-out onto the sample so that what is out of the freezer right now is one query, not a walk of the audit trail. The same mechanism carries the FR-031 reservation expiry.','A checked-out sample carries the timestamp and the actor, updated in the same transaction as the check-out|Check-in clears the attribute in the same transaction as the check-in|The attribute is derivable from the audit trail and a consistency check proves the two agree|Grids and the finder can filter and sort on it|An expired TTL reservation is visible through the same attribute without a background sweep having to have run','PR-017','I2','S','pr-048-checkout-attribute','todo','2026-08-26T17:20:36Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-049',49,'Storage unit barcodes and 50 by 50 box geometry','FR-074 and NFR-008. Terminal storage units get their own deployment-unique barcode, and box geometry is proven to 50 rows by 50 columns.','A terminal storage unit can be assigned a barcode unique across the deployment, enforced by a database constraint|Scanning a storage barcode resolves to the unit, and an unresolvable barcode returns 404 without revealing whether the id exists elsewhere|Scanned storage input is length-bounded and character-validated, and is never interpolated into a query|Row and column labels render correctly at 50 by 50|The NFR-001 render budget is re-measured for a 2500-slot box and either met or the finding recorded','PR-019','I2','S','pr-049-storage-barcodes','todo','2026-08-26T17:20:37Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-050',50,'Storage and lineage operations as workflow tasks','FR-075. A job task performs check-in, check-out, move, aliquot, derive or a status change directly. The design constraint is that a task must invoke the existing pipeline, never a second write path.','A job template task can be typed as a storage or lineage operation and carries its parameters|Executing the task invokes the corresponding pipeline from spec 17.1 or 17.2, so the audit, status and slot rules apply unchanged|A test proves a task cannot perform an operation the assignee could not perform over REST|A task that fails leaves no partial state and the job records the failure|Optimistic locking on task completion still holds when the task performs a write|A destructive operation is not available as a task type at all, matching the prohibitions in spec 18.2','PR-022','I3','M','pr-050-workflow-storage-actions','todo','2026-08-26T17:20:37Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-051',51,'ELN recall, return for changes and review timeline','FR-077. Reverse edges in the notebook state machine, and a timeline that shows them. CON-004 is unaffected: a signed notebook stays immutable and a recall after signing is an amendment.','A reviewer can return a notebook for changes and the author is notified|An administrator can recall a submitted or approved notebook, with a configurably required reason|A signed notebook cannot be recalled into an editable state; the only route is an amendment revision|Every reverse transition appears on a review timeline with actor, timestamp and reason|The state machine is covered by a test per edge including the refusals','PR-025','I4','M','pr-051-eln-recall','todo','2026-08-26T17:20:37Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-052',52,'Configurable signature attestation','FR-078. The wording a signer attests to is configuration, and the wording in force at signing time is bound into the signature.','The attestation text is configurable per deployment|The exact text shown is stored with the signature and included in the hashed content|Changing the text does not alter or invalidate any existing signature|The stored text appears in the exported PDF and in the trail export|A signature whose stored attestation is missing fails verification rather than passing quietly','PR-026','I4','S','pr-052-attestation-text','todo','2026-08-26T17:20:37Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-053',53,'Restricted-node rendering in lineage and timeline','CON-015 and FR-079. Close the lineage, timeline and ELN-reference read paths against cross-boundary identifier leakage, and let status filter the graph.','A node the caller may not read is rendered as restricted with no name, no id and no type, or omitted, whichever ADR is written; the choice is recorded not defaulted|A test proves the lineage endpoint, the timeline endpoint and the ELN reference list each refuse to disclose an unreadable object''s identifier|Edge structure between visible nodes is preserved when an intermediate node is restricted|The graph can be filtered by sample status, with edges contracted across hidden nodes|Counts and aggregates do not reveal the existence of unreadable rows','PR-029','I5','S','pr-053-restricted-lineage','todo','2026-08-26T17:20:37Z');
INSERT INTO backlog(id,seq,title,summary,acceptance,depends_on,iteration,size,branch,status,created_at) VALUES('PR-054',54,'LabKey compatibility contract for the bridge','CON-016, CON-017 and CON-018. Pin the LabKey version the bridge targets, assert the behaviours it depends on, and fail the suite on drift rather than in production.','The bridge records the LabKey version it was verified against and surfaces it in the runbook|Each publish call targets the container that receives the rows; a test proves no call imports across containers|The bridge passes no audit-suppressing parameter, and a test asserts the absence rather than the behaviour|An integration test pins each behavioural claim the bridge relies on, so a LabKey upgrade breaks a test instead of leaving the documentation wrong|A version mismatch fails the integration suite with a message naming the observed and expected versions|No LabKey schema or object name is hard-coded in more than one place','PR-031','I6','M','pr-054-labkey-compat-contract','todo','2026-08-26T17:20:37Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-001','PR-001',1,'Environment-only credential configuration','src/osm/labkey/config.py: LK_URL, LK_USER, LK_PASSWORD, LK_APIKEY, LK_CONTEXT, LK_INSECURE, LK_TIMEOUT. No credential default. Credential fields excluded from repr.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-002','PR-001',2,'Loopback-only TLS relaxation','Verification is skipped only for loopback hosts unless LK_INSECURE is set, because the deployment certificate is self-signed. A remote host must verify.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-003','PR-001',3,'Session bootstrap and CSRF capture','Probes login-whoAmI.api across context candidates, falls back to login-loginApi.api with email and password, absorbs the CSRF token from either the body or the cookie.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-004','PR-001',4,'Transport policy: no redirects, preserved 4xx bodies','allow_redirects=False everywhere; an unexpected 3xx is surfaced with its Location; LabKeyError carries action, status, body, url and exceptionClass.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-005','PR-001',5,'Success is not a status code','A call succeeds only when the status is 2xx and the body reports neither success:false nor an exception. A tolerate list supports idempotent creation.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-006','PR-001',6,'Guard against action names that do not exist','query-importData.api, experiment-saveMaterials.api and experiment-deriveSamples.api fail locally with the correct alternative, turning a confusing 404 into an actionable message.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-007','PR-001',7,'Credential redaction in logs and errors','Payloads are recursively redacted before logging; a rejected login never echoes a reflected password.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-008','PR-001',8,'Verification harness','scripts/verify_labkey.py runs eight read-only probes and can write verification rows through tools/memory.py.','done','2026-08-26T08:59:33Z');
INSERT INTO tasks(id,pr_id,seq,title,detail,status,created_at) VALUES('T-009','PR-001',9,'Unit and integration tests','78 unit tests with no network access, and 11 read-only integration tests marked labkey that pin the ground-truth claims so a LabKey upgrade breaks a test rather than the documentation.','done','2026-08-26T08:59:33Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-001','LabKey CE 26.7.5 exposes no inventory/storage/freezer/workflow/eln schema','http','POST /home/query-getSchemas.api {includeHidden:true}','pass','Returned: announcement, assay, auditLog, cluster, core, exp, exp.data, exp.materials, flow, issues, ListManager, lists, ms2, pipeline, plate, protein, query, samples, study, targetedms, targetedmslists, wiki. None of inventory/storage/freezer/sampleManager/workflow/eln/labbook present.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-002','exp.SampleStateType offers only three state types against the eight statuses OSM spec 3 requires','http','POST /home/query-selectRows.api {schemaName:exp, queryName:SampleStateType}','pass','rowCount 3: Available(0), Consumed(1), Locked(2). exp.SampleStatus is empty (0 rows).','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-003','The host provides PostgreSQL 18.6, Python 3.11.13, Node 24.14.0, JDK 21, sqlite 3.43.2 and git 2.53.0','shell','psql --version; python3 -V; node -v; java -version; sqlite3 --version; git --version','pass','All present. PostgreSQL 18.6 supports btree_gist, required by ADR-0004.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-004','exp.Materials carries aliquot, amount and status columns natively in CE','http','POST /home/query-getQueryDetails.api {schemaName:exp, queryName:Materials}','pass','42 columns including RootMaterialRowId, AliquotedFromLSID, IsAliquot, AliquotCount, AliquotVolume, AliquotUnit, AvailableAliquotCount, AvailableAliquotVolume, StoredAmount, Units, RawAmount, SampleState, MaterialExpDate, IsPlated, Ancestors.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-005','The auditLog schema is queryable and includes SampleTimelineEvent','http','POST /home/query-getQueries.api {schemaName:auditLog}','pass','37 queries including SampleTimelineEvent, SampleSetAuditEvent, ExperimentAuditEvent, TransactionAuditEvent, QueryUpdateAuditEvent.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-006','Login via POST /login-loginApi.api with email and password returns a CSRF token usable as the X-LABKEY-CSRF header','http','POST /login-loginApi.api email=<user> password=<from env>; then GET /login-whoami.api','pass','HTTP 200, success true, CSRF returned and matching the X-LABKEY-CSRF cookie. whoami confirms the authenticated principal. Credentials supplied via environment variables only.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-007','The deployed LabKey tree contains no premium modules','source','list /root/scicore/build/deploy/modules','pass','43 modules: platform 23, commonAssays 10, DiscvrLabKeyModules 8, LabDevKitModules 2, targetedms 1, scicoreBrand 1. No sampleManager, inventory, biologics, labbook, recipe, compliance or premium module present.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-008','InventoryService, SampleStatusService, ComplianceService and McpService are unimplemented SPI stubs in CE','source','read /root/scicore/server/modules/platform/api/src/org/labkey/api/{inventory,qc,compliance,mcp}/*.java','pass','InventoryService.get() returns null. SampleStatusService falls back to DefaultSampleStatusService: supportsSampleStatus() false, isOperationPermitted() always true. ComplianceService falls back to a pass-through. McpService.get() returns NoopMcpService with isEnabled() false.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-009','LabKey CE has no row-level security on exp.material','source','read /root/scicore/server/modules/platform/experiment/src/org/labkey/experiment/api/ExpMaterialTableImpl.java:1844-1860','pass','Every branch of hasPermission() delegates to Container.hasPermission(). No SimpleFilter on CreatedBy, no owner check, no per-row policy. Neither ExpMaterial nor ExpSampleType implements SecurableResource, so samples cannot carry ACLs.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-010','LabKey CE search has no faceting','source','grep -r facet /root/scicore/server/modules/platform/search /root/scicore/server/modules/platform/api/src/org/labkey/api/search','pass','Zero occurrences of facet; no lucene-facet dependency. Only category filtering via OR''d TermQuery on searchCategories. SearchResult returns totalHits, hits, offset with no counts or aggregations.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-011','The Unique ID barcode field type is server-supported in CE but hidden by the UI','source','read ColumnRenderPropertiesImpl.java:48-49, BaseColumnInfo.java:653-665, build/deploy/modules/core/web/gen/domainDesigner.*.js','pass','STORAGE_UNIQUE_ID_CONCEPT_URI drives a DbSequence-backed auto-generated value server-side. The bundled field editor refuses the type when isCommunityDistribution(), but there is no server-side gate: property-createDomain.api with that conceptURI still works.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-012','LabKey CE ships no OIDC, SAML, CAS or LDAP authentication provider','source','enumerate AuthenticationProvider implementations under /root/scicore/server/modules','pass','Only DbLoginAuthenticationProvider (password plus API keys), LoginAttemptDisableLoginProvider, and two devtools-only test providers. OpenLdapSync syncs users and groups but contains no AuthenticationProvider.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-013','API keys exist in CE but are disabled by default','source','read /root/scicore/server/modules/platform/api/src/org/labkey/api/settings/SiteSettingsProperties.java:125-146 and AppPropsImpl.java:546-561','pass','allowApiKeys and allowSessionKeys both default to false. core.APIKeys stores only a SHA-256 crypt. Keys are 64-char hex with no prefix. RestrictionRole allows minting a reduced-privilege key limited to Reader, Author, EditorWithoutDelete or Editor.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-014','The bulk import action is named query-import.api, not query-importData.api','source','read /root/scicore/server/modules/platform/query/src/org/labkey/query/controllers/QueryController.java:4147','pass','ImportAction extends AbstractQueryImportAction resolves to query-import.api. This is the endpoint behind LABKEY.Query.importData. The user''s own scripts confirm the same name.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-015','experiment-saveMaterials.api does not exist and experiment-deriveSamples is a view rather than an API','source','grep for SaveMaterialsAction and DeriveSamplesAction across /root/scicore/server/modules','pass','No SaveMaterialsAction class anywhere. DeriveSamplesAction extends FormViewAction, so it serves experiment-deriveSamples.view. The programmatic derivation endpoint is experiment-derive.api (DeriveAction, Insert permission).','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-016','PHI column tagging exists in CE but masks nothing','source','read /root/scicore/server/modules/platform/api/src/org/labkey/api/data/PHI.java, compliance/PhiColumnBehavior.java, FilteredTable.applyTableRules','pass','The PHI enum, PhiColumnBehavior and the FilteredTable call sites all exist, but no module registers a ComplianceService, so DefaultComplianceService passes everything through with getMaxAllowedPhi() = Restricted. PHI tags survive export and import but provide no protection.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-017','The laboratory module deployed on this server contains a freezer model separate from exp.material','source','read /root/scicore/server/modules/LabDevKitModules/laboratory/resources/schemas/dbscripts/postgresql/laboratory-12.24-12.25.sql:40 and laboratory.xml:91','pass','laboratory.freezers(rowid,name,canes,boxes,rows,columns,comments,container) and laboratory.samples(freezerid,location,freezer,cane,box,box_row,box_column,quantity,...) exist. Not integrated with Sample Types, no slot exclusion constraint, no reservation TTL, no atomic move.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-018','LabKey CE sample tables audit at DETAILED level by default, storing before and after record maps','source','read ExpMaterialTableImpl.java:2019 and SampleTimelineAuditProvider.java','pass','getAuditBehavior() returns DETAILED for sample tables. SampleTimelineEvent carries oldRecordMap and newRecordMap plus TransactionID, with canDeleteOldRows() false. No hash chaining, no checkpoint, so tampering by a database administrator is undetectable.','2026-08-26T08:41:57Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-019','The OSM LabKey client authenticates, discovers the context path and captures a CSRF token against the live server','http','scripts/verify_labkey.py against https://127.0.0.1:8443','pass','8 of 8 probes pass. Session established at https://127.0.0.1:8443 as dcasota@gmail.com, CSRF captured, base context is the root rather than /labkey.','2026-08-26T08:59:33Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-020','The live server exposes 24 schemas in /home and none of inventory, storage, freezer, workflow, eln or labbook','http','scripts/verify_labkey.py probe_schemas','pass','CustomProteinAnnotations, CustomProteinAnnotationsWithSequences, ListManager, announcement, assay, auditLog, cluster, core, exp, exp.data, exp.materials, flow, issues, lists, ms2, pipeline, plate, protein, query, samples, study, targetedms, targetedmslists, wiki.','2026-08-26T08:59:33Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-021','A LabKey 4xx response body survives the client round trip, as spec 16.2 requires for FAILED outbox rows','http','pytest -m labkey tests/test_labkey_integration.py::test_a_bad_query_name_preserves_the_server_explanation','pass','Requesting query-getQueryDetails.api for a non-existent query returns a body that reaches LabKeyError.body intact.','2026-08-26T08:59:33Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-022','The memory CLI round-trips every entity kind and refuses malformed identifiers, duplicate ids, invalid enum values and dangling foreign keys','shell','pytest tests/test_memory_cli.py','pass','68 subprocess-driven tests against a throwaway database. Covers init, add for all seven entity kinds, show, list with a where clause, set, link, query, dump, rebuild, batch and check.','2026-08-26T09:12:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-023','The memory dump is byte-identical across a dump to db to dump cycle, and insertion order does not affect it','shell','pytest tests/test_memory_cli.py -k determinis or dump','pass','Confirmed on a seeded database and independently on the real project database. Fixed table order plus an explicit ORDER BY per table make the text stable, which is what keeps the git diff reviewable (ADR-0007).','2026-08-26T09:12:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-024','tools/memory.py check fails on a stale dump, a dangling dependency, a duplicate sequence number, an unresolvable traceability edge and an untraced requirement','shell','pytest tests/test_memory_cli.py -k check','pass','Each failure mode is asserted to exit 2 and to name the offending id. Two gaps were found and fixed: the gate did not check traceability edges of kind decision, feature or verification, and it did not fail on an untraced requirement at all.','2026-08-26T09:12:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-025','tools/render_backlog.py --check detects drift between the memory database and the generated markdown','shell','pytest tests/test_render_backlog.py','pass','20 tests. Drift is detected after a status change, after a new item is added, after a hand edit and after a file is deleted. --check is proven not to modify the tree. An --out-dir option was added so the renderer can be tested in isolation rather than against the repository.','2026-08-26T09:12:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-026','The committed knowledge base satisfies its stated invariants: 97 requirements all traced, backlog dependencies acyclic and topologically ordered, ADR numbering contiguous, no dangling cross-references','shell','pytest tests/test_memory_invariants.py','pass','50 tests read the committed dump rather than a local working file. Also asserts every requirement cites a spec section, every backlog item has between 2 and 12 acceptance criteria and a branch name matching its id, every ADR has a markdown file and vice versa, and no feature or research row rests on an unfinished assessment.','2026-08-26T09:12:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-027','No credential-shaped literal appears in any tracked file, enforced by a scanner that is itself proven to fire on planted secrets','shell','pytest tests/test_no_secrets.py','pass','23 tests scanning every git-tracked file for private key blocks, GitHub, HuggingFace, AWS, Slack and JWT tokens, credentials embedded in URLs, and credential-shaped assignments. Eight planted-secret cases prove the scanner fires; eight safe-content cases prove it does not cry wolf. An exact-value allowlist means a new placeholder is a deliberate, reviewable act.','2026-08-26T09:12:06Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-028','The LabKey client refuses to relax TLS towards a non-loopback host by default, and never relaxes silently when explicitly told to','shell','pytest tests/test_labkey_config.py -k tls or relax','pass','Default for a remote host is verify=True across hostnames and private addresses. An explicit LK_INSECURE=1 on a remote host is honoured, per ADR-0008, but now emits a WARNING naming the host; the ordinary loopback case stays quiet so the warning keeps its signal.','2026-08-26T09:12:06Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-029','The full test suite passes: 251 unit tests without network access and 11 read-only integration tests against the live LabKey server','shell','make check; pytest -m labkey','pass','251 passed, 11 deselected in the unit run; 11 passed against https://127.0.0.1:8443. make check additionally runs tools/memory.py check and tools/render_backlog.py --check. Warnings are errors, with a single documented exception for the expected loopback InsecureRequestWarning.','2026-08-26T09:12:06Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-030','LabKey has never shipped a hash-chained or tamper-evident audit trail','doc','text search for ''hash'' and ''tamper'' across the wiki bodies of all 60 fetched LabKey server release-notes pages, 2.1 to 26.11','pass','Zero occurrences of ''hash'' and zero of ''tamper'' across all 60 pages. Also zero occurrences of ''21 CFR'', ''Part 11'', ''GxP'' and ''GMP'' in the server notes, and exactly one in the 83 LIMS sections. ADR-0003 has no prior art to follow and no compatibility to preserve. doc-grade evidence only; it establishes what LabKey announced, not what LabKey implements.','2026-08-26T17:22:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-031','LabKey removed the Specimen Repository from Community Edition in release 21.3','doc','read https://www.labkey.org/Documentation/Archive/21.3/wiki-page.view?name=releaseNotes213','pass','Stated twice on the page: ''Specimen functionality has been removed from the study module ... Do not upgrade a Community Edition if you want to continue using specimen as part of study'' and ''Specimen Repository functionality has been removed from all standard distributions (Community, Starter, Professional, and Enterprise).'' Announced in advance in 20.11. With FreezerPro and SampleMinded support both removed in 25.3, Community Edition has had no vial or freezer capability from any direction since March 2025.','2026-08-26T17:22:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-032','The LabKey MCP Server is a premium feature in 26.3 and 26.7','doc','read https://www.labkey.org/Documentation/Archive/26.3/wiki-page.view?name=releaseNotes263 and https://www.labkey.org/Documentation/wiki-page.view?name=releasenotes267','pass','Both releases list the MCP Server under ''Premium Edition Feature Updates''. This agrees with the source-level finding in docs/labkey-ce-ground-truth.md that CE registers no McpService implementation and McpService.get() returns NoopMcpService with isEnabled() false. A rare case where the documentation and the implementation agree; recorded because most of the traps in this project are cases where they do not.','2026-08-26T17:22:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-033','LabKey CE 25.11 forces detailed audit logging on samples and prevents an API caller lowering the level','doc','read https://www.labkey.org/Documentation/Archive/25.11/wiki-page.view?name=releaseNotes2511','partial','The page states, under Community Edition Updates, that ''Detailed audit logging is automatically enabled for Samples, Sources, Data Classes, and Assay Data'' and that ''API users are now prevented from reducing the audit level below the effective default or the administrator-configured value.'' PARTIAL because this is doc-grade only. Whether an auditBehavior parameter is rejected or merely ignored is not stated and has not been tested against the running server. PR-039 closes it. CON-017 is written so that the bridge is correct either way.','2026-08-26T17:22:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-034','The LabKey LIMS release notes are published as per-release pages, like the server archive','doc','fetch https://www.labkey.org/limshelp/wiki-page.view?name=limsSuiteReleaseNotes and parse all 369 hrefs in the body and navigation tree','fail','FALSE. It is a single consolidated page with 83 release sections. No href points to a per-version LIMS release-notes page, no /limshelp/Archive/ URLs exist, and the navigation tree has one child page (limsApiReleaseNotes). Recorded as a failure because the assumption shaped the research plan: repeating the server-archive method here would have produced a page of fabricated 404s. Deriving URLs from links that actually exist, rather than from a pattern, is what caught it.','2026-08-26T17:22:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-035','The releaseNotes{MM} archive URL pattern advertised by the Previous Releases page resolves for every listed release','doc','fetch https://www.labkey.org/Documentation/Archive/{v}/wiki-page.view?name=releaseNotes{MM} for all 59 listed versions','fail','FALSE for the ten releases before 10.1. 2.0, 2.1, 2.2, 2.3, 8.1, 8.2, 8.3, 9.1, 9.2 and 9.3 all 404 on the advertised pattern. 8.1 to 9.3 resolve as whatsnew{MM} and 2.1 to 2.3 as whatsNew; 2.0 has no release-notes page under any name, and Archive/2.0/project-begin.view returns 200 with no such link in its navigation. Nine of the ten were recovered by probing alternates rather than by assuming the pattern held.','2026-08-26T17:22:05Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-036','The LabKey MCP Server is documented as premium, and API keys are documented as Community','doc','read https://www.labkey.org/Documentation/wiki-page.view?name=mcp and https://www.labkey.org/Documentation/wiki-page.view?name=apiKey','pass','The MCP page carries ''Premium Feature - Available in the Professional and Enterprise Editions of LabKey SDMS.'' The apiKey and apiSessionKey pages carry no premium badge and no star. This is consistent with ground truth: CE ships the MCP framework with no implementation registered, and CE API keys support restriction roles. The MCP page also describes the tool surface as letting agents ''discover datasets, run SQL queries, and perform analysis'' - the executeSQL capability PRO-009 forbids OSM from exposing.','2026-08-26T17:28:48Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-037','Every LabKey Sample Manager and LIMS documentation page is behind a paywall','doc','parse the ''Available in:'' badge chips on 107 fetched /limshelp pages','pass','The complete observed chip vocabulary is exactly SM Starter, SM Professional, LIMS Starter, LIMS Enterprise and Biologics LIMS. No ''Community'' chip appears anywhere in the container. Corroborated by labkey.com''s Sample Manager pricing table, which has only Starter and Professional columns, both paid. Freezer management, check-in and check-out, workflow, the ELN, picklists, the Sample Finder, sample status and the sample timeline are all inside this container.','2026-08-26T17:28:48Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-038','LabKey documents point-in-time recovery or a restore drill for some edition','doc','read dbBackup, backupRestore, backupChecklist, backupScenarios and enterprisePlan on https://www.labkey.org/Documentation','fail','FALSE. None of the five pages carries a premium badge or a star, and none documents point-in-time recovery or a restore drill. LabKey''s documented backup story is pg_dump and pg_restore guidance, available to everybody. The only edition-linked backup item found in a 265-page sweep is a hosted-service retention SLA on labkey.com''s Sample Manager pricing page (90 days Starter, 180 days Professional). OSM''s NFR-006 and PR-038 exceed the commercial product; there is no prior art to copy.','2026-08-26T17:28:48Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-039','The documentation page names suggested for the premium sweep resolve','doc','fetch 17 probed /Documentation and /limshelp page names','fail','FALSE for all 17. folderArchive, backupAndRestore, exportFolder, importFolder, etl, ssoConfig, sampleManager, antiVirus, virusCheck, encryptionKey, limitActiveUsers, labkeyDataFinder, inventoryStorage, storage, dataspace, bioProject and bioregistry all return HTTP 200 with the body ''This page has no content.'' - LabKey''s soft-404, which means a 200 status is not evidence a page exists. Correct names recorded in docs/premium-feature-gap.md section 18. ''phi'' is a 301 redirect to ''phiLevels'', not a 404. Recorded because a soft-404 returning 200 will silently corrupt any crawl that trusts status codes.','2026-08-26T17:28:48Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-040','LabKey ships five official client API libraries - Java, JavaScript/TypeScript, Python, Perl and R - and no Rust client','http','gh api ''search/repositories?q=org:LabKey+labkey-api+in:name''; gh api ''search/repositories?q=org:LabKey+language:Rust''','pass','labkey-api-java, labkey-api-js (TypeScript), labkey-api-python (Apache-2.0, 25 stars), labkey-api-perl, labkey-api-r (Apache-2.0). Rust repository count in the LabKey org is 0. labkey-api-perl was last pushed 2022-07-14; the other four were pushed within the last two months (checked 2026-08-27). The client libraries are separate repositories, not vendored in the server enlistment: /root/scicore/clientAPIs and /root/scicore/remoteapi are empty checkout directories whose READMEs say so.','2026-08-27T12:06:45Z');
INSERT INTO verifications(id,claim,method,command,result,detail,verified_at) VALUES('V-041','labkey-rs is a third-party Rust client for the LabKey REST API, not a LabKey product','http','gh api repos/nrminor/labkey-rs; curl https://crates.io/api/v1/crates/labkey-rs','pass','github.com/nrminor/labkey-rs, crate labkey-rs 0.2.2 on crates.io, dual MIT OR Apache-2.0, created 2026-03-04, last pushed 2026-04-17, 259 downloads, 0 stars, 0 forks, 0 open issues. Its README states plainly that it is unofficial, unsupported by LabKey and outside the official client suite. It is a port of @labkey/api (labkey-api-js) v1.48.0 supplemented by the Java client for endpoint coverage. Async over reqwest 0.13 with typed builders (bon); modules include query, filter, domain, assay, experiment, list, security, storage and specimen.','2026-08-27T12:06:45Z');
